  var st=document.createElement('style'); st.textContent="/* Layout: one featured card, today's Aliyah on top; a 7-day strip shows where we are in the week. Colours follow thewayderech.co.za (red + charcoal on white). */\n.tw-aliyah{\n  --red:#c70c0f; --red-soft:#fbeaea; --ink:#1c1c1c; --muted:#5f5a58; --rule:#e6e1df; --paper:#ffffff; --tint:#f8f6f5;\n  --f-head:\"Poppins\", Arial, sans-serif; --f-body:\"Cantarell\", Arial, sans-serif;\n  color-scheme:light; background:var(--paper); color:var(--ink); font-family:var(--f-body); font-size:17px; line-height:1.65;\n  padding-left:max(16px, env(safe-area-inset-left, 0px)); padding-right:max(16px, env(safe-area-inset-right, 0px)); padding-block:28px 36px;\n}\n.tw-aliyah *{box-sizing:border-box}\n.tw-in{max-width:760px;margin:0 auto}\n.tw-top{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}\n.tw-eyebrow{font-family:var(--f-head);font-weight:600;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--red);display:flex;align-items:center;gap:8px}\n.tw-eyebrow .dot{width:8px;height:8px;border-radius:50%;background:var(--red);box-shadow:0 0 0 4px var(--red-soft)}\n.tw-date{color:var(--muted);letter-spacing:.06em}\n.tw-lang{display:inline-flex;border:1px solid var(--rule);border-radius:999px;padding:3px}\n.tw-lang button{font:600 12px/1 var(--f-head);letter-spacing:.06em;border:0;background:transparent;color:var(--muted);padding:7px 12px;border-radius:999px;cursor:pointer}\n.tw-lang button[aria-pressed=\"true\"]{background:var(--ink);color:#fff}\n\n.tw-week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;margin:0 0 22px}\n.tw-day{font-family:var(--f-head);border:1px solid var(--rule);background:var(--paper);border-radius:8px;padding:8px 2px 7px;text-align:center;cursor:pointer;color:var(--ink);display:grid;gap:1px}\n.tw-day b{font-size:16px;font-weight:600;line-height:1.2}\n.tw-day small{font-size:10.5px;letter-spacing:.04em;color:var(--muted);text-transform:uppercase}\n.tw-day[aria-current=\"true\"]{background:var(--red);border-color:var(--red);color:#fff}\n.tw-day[aria-current=\"true\"] small{color:#fff}\n.tw-day:disabled{cursor:default;background:var(--tint);color:#b7b0ad;border-style:dashed}\n.tw-day:disabled small{color:#c3bcb9}\n.tw-day:focus-visible,.tw-lang button:focus-visible,.tw-links a:focus-visible{outline:2px solid var(--ink);outline-offset:2px}\n\n.tw-card{border-top:4px solid var(--red);background:var(--paper)}\n.tw-head{padding:22px 0 6px}\n.tw-ref{font-family:var(--f-head);font-weight:600;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:0 0 14px}\n.tw-ref span{color:var(--red)}\n.tw-bless{font-style:italic;color:var(--muted);margin:0 0 10px}\n.tw-hook{font-family:var(--f-head);font-weight:700;font-size:clamp(26px,5vw,38px);line-height:1.15;letter-spacing:-.01em;margin:0 0 18px;text-wrap:balance}\n.tw-sum{margin:0 0 26px;padding:16px 18px;background:var(--tint);border-radius:8px}\n.tw-qs{list-style:none;margin:0;padding:0;display:grid;gap:26px;counter-reset:q}\n.tw-q{display:grid;grid-template-columns:36px minmax(0,1fr);gap:0 14px}\n.tw-q::before{counter-increment:q;content:counter(q);font-family:var(--f-head);font-weight:700;font-size:15px;width:32px;height:32px;border-radius:50%;border:2px solid var(--red);color:var(--red);display:grid;place-items:center;margin-top:2px}\n.tw-q h3{font-family:var(--f-head);font-weight:600;font-size:18px;line-height:1.35;margin:0 0 6px;text-wrap:balance}\n.tw-q h3 .r{font-weight:500;color:var(--muted);font-size:14px;white-space:nowrap}\n.tw-q p{margin:0 0 8px}\n.tw-key{margin:6px 0 10px;padding-left:14px;border-left:3px solid var(--rule)}\n.tw-key p{font-style:italic;font-weight:700;margin:0 0 4px}\n.tw-act{background:var(--red-soft);border-radius:8px;padding:12px 14px}\n.tw-act strong{font-family:var(--f-head);font-weight:600;color:var(--red);font-size:13px;letter-spacing:.06em;text-transform:uppercase;display:block;margin-bottom:2px}\n.tw-act .h{font-weight:700;display:block}\n.tw-act p{margin:4px 0 0}\n.tw-deep{margin:30px 0 0;padding:18px 20px;border:1px solid var(--rule);border-left:4px solid var(--red);border-radius:8px}\n.tw-deep h3{font-family:var(--f-head);font-weight:600;font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--red);margin:0 0 6px}\n.tw-deep p{margin:0}\n.tw-close{margin:30px 0 0;padding:22px 20px;background:var(--ink);color:#fff;border-radius:10px}\n.tw-close small{font-family:var(--f-head);font-weight:600;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#ff9c9d;display:block;margin-bottom:6px}\n.tw-close p{font-family:var(--f-head);font-weight:600;font-size:20px;line-height:1.35;margin:0}\n.tw-close p+p{font-family:var(--f-body);font-weight:400;font-size:16px;margin-top:8px}\n.tw-links{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px;font-family:var(--f-head);font-size:14px}\n.tw-links a{text-decoration:none;font-weight:600;padding:10px 16px;border-radius:999px;border:1px solid var(--ink);color:var(--ink)}\n.tw-links a.p{background:var(--red);border-color:var(--red);color:#fff}\n.tw-empty{padding:28px 0;color:var(--muted)}\n@media (max-width:520px){\n  .tw-aliyah{font-size:16px}\n  .tw-day small{font-size:9.5px}\n  .tw-q{grid-template-columns:30px minmax(0,1fr);gap:0 10px}\n  .tw-q::before{width:28px;height:28px;font-size:13px}\n}\n.tw-perma{margin:22px 0 0;font-family:var(--f-head);font-size:13px}\n.tw-perma a{color:var(--muted)}\n"; document.head.appendChild(st);
  root.innerHTML="<section class=\"tw-aliyah\" id=\"tw-aliyah\" aria-label=\"Aliyah of the Day\">\n  <div class=\"tw-in\">\n    <div class=\"tw-top\">\n      <div class=\"tw-eyebrow\"><span class=\"dot\" aria-hidden=\"true\"></span><span id=\"tw-label\">Aliyah of the Day</span><span class=\"tw-date\" id=\"tw-date\"></span></div>\n      <div class=\"tw-lang\" role=\"group\" aria-label=\"Language\">\n        <button type=\"button\" id=\"tw-en\" aria-pressed=\"true\">English</button>\n        <button type=\"button\" id=\"tw-af\" aria-pressed=\"false\">Afrikaans</button>\n      </div>\n    </div>\n    <div class=\"tw-week\" id=\"tw-week\" role=\"group\" aria-label=\"This week's Aliyot\"></div>\n    <article class=\"tw-card\" id=\"tw-card\" aria-live=\"polite\"></article>\n    <div class=\"tw-links\">\n      <a class=\"p\" href=\"https://t.me/+VG6F0CBWsCKG2KgI\" target=\"_blank\" rel=\"noopener\" id=\"tw-tg\">Join us on Telegram</a>\n      <a href=\"https://chat.whatsapp.com/HZhD7k7usKQI3E9u4mhv1K\" target=\"_blank\" rel=\"noopener\" id=\"tw-wa\">Join the WhatsApp group</a>\n    </div>\n  </div>\n</section>\n";
  var BASE="https://thewaydhymin-eng.github.io/Aliyah";
  var ALIYOT=[{"date":"2026-11-08","parashah":"Toldot","year":"5787","aliyah":1,"ref":"Bereishit 25:19–26:5","en":{"title":"What Hunger Sells","blessing":"Shavuah Tov! May this week’s first Aliyah teach us to value what יהוה has given above what our hunger demands.","hook":"Esav sold his birthright for one meal and walked away satisfied.","summary":"Yitzchak pleads with יהוה for Rivkah because she is barren, and she conceives twins who struggle within her. יהוה tells her that two nations are in her womb and that the older will serve the younger; Esav is born first, and Yaakov follows holding his heel. Years later Esav comes in exhausted from the field and sells his birthright to Yaakov under oath for bread and lentil stew, and the text says he despised it. When famine comes, יהוה tells Yitzchak not to go down to Egypt but to stay in the land, and confirms to him the oath He swore to Avraham, because Avraham obeyed His voice.","questions":[{"q":"What did Esav do with his birthright?","ref":"25:29–34","answer":"He sold it to Yaakov under oath for bread and lentil stew, then ate, drank, rose and went his way.","key":["The text gives its own verdict: Esav despised his birthright.","When the meal was finished, he showed no sense of loss."],"action":"Name what you are trading for immediate relief.","detail":"Write down one thing of lasting value you have been neglecting because something else feels more urgent today. Next to it, write what that urgency is really offering you."},{"q":"Why does Yitzchak receive the promise “because Avraham obeyed”?","ref":"26:2–5","answer":"יהוה confirms His oath to Yitzchak and gives the reason: Avraham obeyed His voice and kept His charge, His commandments, His statutes and His Torot.","key":["Long before Sinai, the text already speaks of commandments, statutes and Torot.","One generation’s obedience shapes the blessing spoken over the next."],"action":"Let someone after you see one commandment you keep.","detail":"Choose one command you keep faithfully, such as Shabbat, honest dealing or giving. Explain to a child, grandchild or younger believer why you keep it."},{"q":"How does the Brit Chadashah use Esav as a warning?","ref":"25:34; Hebrews 12:16–17","answer":"The writer of Hebrews warns believers not to be like Esav, who sold his birthright for a single meal and later could not undo it, though he sought the blessing with tears.","key":["Bereishit records the sale. Hebrews records the cost.","A moment of appetite can have consequences that tears cannot reverse."],"action":"Read Hebrews 12:14–17 beside Bereishit 25:29–34.","detail":"Mark what the writer of Hebrews calls Esav. Then ask where the same attitude has room in your own life."},{"q":"What am I treating as worthless because it does not feed me today?","ref":"25:32","answer":"Esav reasoned that he was about to die, so what use was a birthright to him.","key":["He measured an inheritance by the needs of one afternoon.","I can call something set apart “useless” simply because its value lies in the future."],"action":"Restore one inheritance you have been treating as optional.","detail":"It may be your Shabbat, your time in the Word, your family’s instruction in the Torah or your covenant faithfulness. Put it back in your diary this week, at a fixed time."},{"q":"Will I stay where יהוה placed me when hunger pushes me toward Egypt?","ref":"26:1–3","answer":"During the famine, יהוה told Yitzchak not to go down to Egypt but to stay in the land He would show him, and promised to be with him.","key":["Hunger appears twice in this Aliyah: Esav’s and the land’s.","Esav let his hunger decide. Yitzchak was told to let יהוה decide."],"action":"Stay faithful in one place where pressure is pushing you to leave obedience.","detail":"Name the “Egypt” that looks like the easy answer right now: a shortcut at work, a compromise in a relationship or a quick fix with money. Decide today that you will not go down there."}],"closing":"Hunger passes. A birthright does not come back.","actionOfDay":"Before tonight, identify one decision you are about to make out of pressure or appetite. Delay it by 24 hours and bring it before יהוה in prayer before you act.","waSummary":"Esav comes in exhausted and sells his birthright to Yaakov for bread and lentil stew, and the text says he despised it."},"af":{"title":"Wat Honger Verkoop","blessing":"Shavuah Tov! Mag hierdie week se eerste Aliyah ons leer om wat יהוה gegee het, hoër te ag as wat ons honger eis.","hook":"Esav het sy eersgeboortereg vir een maaltyd verkoop en tevrede weggestap.","summary":"Yitzchak pleit by יהוה vir Rivkah omdat sy onvrugbaar is, en sy word swanger met ’n tweeling wat in haar met mekaar worstel. יהוה sê vir haar dat twee nasies in haar skoot is en dat die oudste die jongste sal dien; Esav word eerste gebore, en Yaakov volg met sy hand aan Esav se hakskeen. Jare later kom Esav uitgeput van die veld af en verkoop sy eersgeboortereg onder eed aan Yaakov vir brood en lensiesop, en die teks sê dat hy dit verag het. Wanneer hongersnood kom, sê יהוה vir Yitzchak om nie na Egipte af te trek nie maar in die land te bly, en bevestig aan hom die eed wat Hy aan Avraham gesweer het, omdat Avraham na sy stem geluister het.","questions":[{"q":"Wat het Esav met sy eersgeboortereg gedoen?","ref":"25:29–34","answer":"Hy het dit onder eed aan Yaakov verkoop vir brood en lensiesop, en toe geëet, gedrink, opgestaan en weggegaan.","key":["Die teks lewer self die oordeel: Esav het sy eersgeboortereg verag.","Toe die ete verby was, het hy geen verlies gevoel nie."],"action":"Noem wat jy verruil vir onmiddellike verligting.","detail":"Skryf een ding van blywende waarde neer wat jy afskeep omdat iets anders vandag dringender voel. Skryf langsaan wat daardie dringendheid jou eintlik aanbied."},{"q":"Hoekom ontvang Yitzchak die belofte “omdat Avraham geluister het”?","ref":"26:2–5","answer":"יהוה bevestig sy eed aan Yitzchak en gee die rede: Avraham het na sy stem geluister en sy opdrag, sy gebooie, sy insettinge en sy Torot gehou.","key":["Lank voor Sinai praat die teks reeds van gebooie, insettinge en Torot.","Een geslag se gehoorsaamheid vorm die seën wat oor die volgende uitgespreek word."],"action":"Laat iemand ná jou sien hoe jy een gebod hou.","detail":"Kies een gebod wat jy getrou hou, soos Shabbat, eerlike handel of gee. Verduidelik aan ’n kind, kleinkind of jonger gelowige hoekom jy dit hou."},{"q":"Hoe gebruik die Brit Chadashah vir Esav as waarskuwing?","ref":"25:34; Hebreërs 12:16–17","answer":"Die skrywer van Hebreërs waarsku gelowiges om nie soos Esav te wees nie, wat sy eersgeboortereg vir een maaltyd verkoop het en dit later nie kon ongedaan maak nie, al het hy die seën met trane gesoek.","key":["Bereishit teken die verkoop aan. Hebreërs teken die prys aan.","Een oomblik se aptyt kan gevolge hê wat trane nie kan omkeer nie."],"action":"Lees Hebreërs 12:14–17 saam met Bereishit 25:29–34.","detail":"Merk wat die skrywer van Hebreërs vir Esav noem. Vra dan waar dieselfde houding ruimte in jou eie lewe het."},{"q":"Wat behandel ek as waardeloos omdat dit my nie vandag voed nie?","ref":"25:32","answer":"Esav het geredeneer dat hy op die punt was om te sterf, so wat help ’n eersgeboortereg hom.","key":["Hy het ’n erfenis gemeet aan die behoeftes van een middag.","Ek kan iets wat afgesonder is “nutteloos” noem bloot omdat die waarde daarvan in die toekoms lê."],"action":"Herstel een erfenis wat jy as opsioneel behandel het.","detail":"Dit kan jou Shabbat wees, jou tyd in die Woord, jou gesin se onderrig in die Torah of jou verbondstrou. Sit dit hierdie week terug in jou dagboek, op ’n vaste tyd."},{"q":"Sal ek bly waar יהוה my geplaas het wanneer honger my na Egipte toe stoot?","ref":"26:1–3","answer":"Tydens die hongersnood het יהוה vir Yitzchak gesê om nie na Egipte af te trek nie maar in die land te bly wat Hy hom sou wys, en belowe om by hom te wees.","key":["Honger kom twee keer in hierdie Aliyah voor: Esav s’n en die land s’n.","Esav het sy honger laat besluit. Yitzchak is gesê om יהוה te laat besluit."],"action":"Bly getrou op een plek waar druk jou weg van gehoorsaamheid stoot.","detail":"Noem die “Egipte” wat nou na die maklike antwoord lyk: ’n kortpad by die werk, ’n kompromie in ’n verhouding of ’n vinnige oplossing met geld. Besluit vandag dat jy nie soontoe sal aftrek nie."}],"closing":"Honger gaan verby. ’n Eersgeboortereg kom nie terug nie.","actionOfDay":"Identifiseer voor vanaand een besluit wat jy op die punt staan om uit druk of aptyt te neem. Stel dit 24 uur uit en bring dit in gebed voor יהוה voordat jy optree.","waSummary":"Esav kom uitgeput in en verkoop sy eersgeboortereg vir brood en lensiesop aan Yaakov, en die teks sê dat hy dit verag het."}},{"date":"2026-11-09","parashah":"Toldot","year":"5787","aliyah":2,"ref":"Bereishit 26:6–12","en":{"title":"The Father’s Fear, Repeated","blessing":"Boker Tov! May today’s Aliyah free us from the fears we inherited.","hook":"Yitzchak repeated his father’s lie in the same city.","summary":"Yitzchak settles in Gerar, and when the men of the place ask about Rivkah, he says she is his sister because he fears they will kill him for her. After some time Avimelech sees from a window how Yitzchak treats Rivkah and confronts him: one of the people could easily have taken her, and Yitzchak would have brought guilt on them all. Avimelech orders that anyone who touches Yitzchak or his wife will be put to death. Yitzchak sows in the land and reaps a hundredfold that same year, and יהוה blesses him.","questions":[{"q":"What did Yitzchak say about Rivkah, and why?","ref":"26:6–7","answer":"He told the men of Gerar that she was his sister, because he feared they would kill him for her.","key":["His fear is spelled out in his own reasoning.","It is the same fear and the same answer, in the same city where Avraham said it (20:1–2)."],"action":"Name the fear behind your last half-truth.","detail":"Think of the last time you shaded the truth to protect yourself. Write down in one sentence what you were afraid would happen."},{"q":"How was the lie exposed?","ref":"26:8–10","answer":"Avimelech saw from a window how Yitzchak treated Rivkah, called him in, and confronted him with what his lie could have caused.","key":["A Philistine king had to name the danger: guilt on a whole people.","Deception rarely stays private. Others carry its risk."],"action":"Count who else carries the risk of your silence.","detail":"Take the half-truth you named in question 1. List the people who could be harmed if it continues, and decide what you will say to set it right."},{"q":"What does the Haftarah say belongs on the lips of one who walks with Elohim?","ref":"26:7; Malachi 2:5–6","answer":"In the Haftarah, יהוה describes His covenant with Levi: the Torah of truth was in his mouth, and no injustice was found on his lips.","key":["Malachi makes truthful speech a mark of walking with Elohim in peace and uprightness.","In Gerar, Yitzchak’s words fell short of that mark."],"action":"Read Malachi 2:4–7 and Bereishit 26:6–11 together.","detail":"Write down the qualities Malachi lists in the one who walks with Elohim. Choose one to practise in your speech today."},{"q":"Which of my parents’ patterns am I repeating without noticing?","ref":"26:7; 20:2","answer":"Yitzchak reached for the same self-protective answer his father had used.","key":["Patterns pass down as easily as blessings.","I need to name a family habit before it shapes my children."],"action":"Write down one reaction you learned at home that you do not want to pass on.","detail":"It may be how your family handled anger, money, conflict or the truth. Write the reaction, then write what obedience would look like instead."},{"q":"Where did the harvest come?","ref":"26:12","answer":"Yitzchak sowed in the land where יהוה had told him to stay and reaped a hundredfold that same year, and יהוה blessed him.","key":["The harvest came in the land of obedience, not in Egypt.","Staying where יהוה placed him became the place of increase."],"action":"Sow one thing today in the place where יהוה has put you.","detail":"Invest one concrete effort in your present family, work or congregation instead of waiting for a better place. Do it before the day ends."}],"closing":"Fear repeats itself. So can faithfulness.","actionOfDay":"Choose one area where you have shaded the truth to protect yourself. Before tonight, set it right with the person it affects.","waSummary":"In Gerar, Yitzchak says Rivkah is his sister out of fear, until Avimelech sees the truth and confronts him."},"af":{"title":"Die Vader se Vrees, Herhaal","blessing":"Boker Tov! Mag vandag se Aliyah ons vrymaak van die vrese wat ons geërf het.","hook":"Yitzchak het sy vader se leuen in dieselfde stad herhaal.","summary":"Yitzchak vestig hom in Gerar, en wanneer die manne van die plek na Rivkah vra, sê hy dat sy sy suster is, omdat hy vrees dat hulle hom ter wille van haar sal doodmaak. Ná ’n tyd sien Avimeleg deur ’n venster hoe Yitzchak met Rivkah omgaan en konfronteer hom: een van die mense kon haar maklik geneem het, en Yitzchak sou skuld oor hulle almal gebring het. Avimeleg beveel dat enigeen wat Yitzchak of sy vrou aanraak, doodgemaak sal word. Yitzchak saai in die land en oes dieselfde jaar honderdvoudig, en יהוה seën hom.","questions":[{"q":"Wat het Yitzchak oor Rivkah gesê, en hoekom?","ref":"26:6–7","answer":"Hy het vir die manne van Gerar gesê dat sy sy suster is, omdat hy gevrees het dat hulle hom ter wille van haar sou doodmaak.","key":["Sy vrees word in sy eie redenasie uitgespel.","Dit is dieselfde vrees en dieselfde antwoord, in dieselfde stad waar Avraham dit gesê het (20:1–2)."],"action":"Noem die vrees agter jou jongste halwe waarheid.","detail":"Dink aan die laaste keer toe jy die waarheid verbuig het om jouself te beskerm. Skryf in een sin neer waarvoor jy bang was."},{"q":"Hoe is die leuen ontbloot?","ref":"26:8–10","answer":"Avimeleg het deur ’n venster gesien hoe Yitzchak met Rivkah omgaan, hom geroep en hom gekonfronteer met wat sy leuen kon veroorsaak het.","key":["’n Filistynse koning moes die gevaar benoem: skuld oor ’n hele volk.","Misleiding bly selde privaat. Ander dra die risiko daarvan."],"action":"Tel wie anders die risiko van jou stilte dra.","detail":"Neem die halwe waarheid wat jy in vraag 1 genoem het. Lys die mense wat skade kan ly as dit voortduur, en besluit wat jy sal sê om dit reg te stel."},{"q":"Wat sê die Haftarah hoort op die lippe van een wat met Elohim wandel?","ref":"26:7; Maleagi 2:5–6","answer":"In die Haftarah beskryf יהוה sy verbond met Levi: die Torah van waarheid was in sy mond, en geen onreg is op sy lippe gevind nie.","key":["Maleagi maak eerlike spraak ’n kenmerk van wandel met Elohim in vrede en opregtheid.","In Gerar het Yitzchak se woorde by daardie maatstaf tekortgeskiet."],"action":"Lees Maleagi 2:4–7 en Bereishit 26:6–11 saam.","detail":"Skryf die eienskappe neer wat Maleagi noem by die een wat met Elohim wandel. Kies een om vandag in jou spraak in te oefen."},{"q":"Watter patrone van my ouers herhaal ek sonder om dit agter te kom?","ref":"26:7; 20:2","answer":"Yitzchak het na dieselfde selfbeskermende antwoord gegryp wat sy vader gebruik het.","key":["Patrone word net so maklik oorgedra soos seëninge.","Ek moet ’n familiegewoonte benoem voordat dit my kinders vorm."],"action":"Skryf een reaksie neer wat jy by die huis geleer het en nie wil oordra nie.","detail":"Dit kan wees hoe jou familie met woede, geld, konflik of die waarheid omgegaan het. Skryf die reaksie neer, en skryf dan neer hoe gehoorsaamheid eerder sou lyk."},{"q":"Waar het die oes gekom?","ref":"26:12","answer":"Yitzchak het gesaai in die land waar יהוה hom gesê het om te bly, en dieselfde jaar honderdvoudig geoes, en יהוה het hom geseën.","key":["Die oes het in die land van gehoorsaamheid gekom, nie in Egipte nie.","Om te bly waar יהוה hom geplaas het, het die plek van groei geword."],"action":"Saai vandag een ding op die plek waar יהוה jou gesit het.","detail":"Belê een konkrete poging in jou huidige gesin, werk of gemeente in plaas daarvan om vir ’n beter plek te wag. Doen dit voor die dag om is."}],"closing":"Vrees herhaal homself. Getrouheid ook.","actionOfDay":"Kies een terrein waar jy die waarheid verbuig het om jouself te beskerm. Stel dit voor vanaand reg met die persoon wat daardeur geraak word.","waSummary":"In Gerar sê Yitzchak uit vrees dat Rivkah sy suster is, totdat Avimeleg die waarheid sien en hom konfronteer."}},{"date":"2026-11-10","parashah":"Toldot","year":"5787","aliyah":3,"ref":"Bereishit 26:13–22","en":{"title":"Keep Digging","blessing":"Boker Tov! May today’s Aliyah give us the patience to keep digging.","hook":"Yitzchak kept digging until יהוה made room.","summary":"Yitzchak becomes very great, and the Philistines envy him; they have already stopped up the wells Avraham’s servants dug, filling them with earth. Avimelech sends him away, and Yitzchak settles in the valley of Gerar, where he digs out his father’s wells again and gives them the names his father gave them. His servants find a well of living water, but the herdsmen of Gerar claim it, so he names it Esek and digs another; they quarrel over that one too, and he names it Sitnah. He moves on and digs a third well that no one disputes, and names it Rechovot, saying that יהוה has made room for them to be fruitful in the land.","questions":[{"q":"What did Yitzchak do with the wells the Philistines had stopped?","ref":"26:15, 18","answer":"He dug them out again and called them by the same names his father had given them.","key":["He reopened what his father had opened.","He kept his father’s names on them."],"action":"Reopen one well your fathers in the faith dug.","detail":"Choose one practice handed down to you that has fallen silent, such as a blessing at the table, a prayer or a Scripture you once knew by heart. Restore it this week."},{"q":"Why did Yitzchak move on from Esek and Sitnah?","ref":"26:20–22","answer":"Each time the herdsmen of Gerar claimed the water, he named the well after the strife and dug another, until he found one that no one disputed.","key":["Esek means contention, Sitnah means hostility, and Rechovot means wide spaces.","He did not fight for every well. Room came after he moved on."],"action":"Name your Esek and your Sitnah.","detail":"Identify one conflict you keep returning to over something that is not essential. Write down what you would gain by digging elsewhere."},{"q":"How does Yeshua speak of living water?","ref":"26:19; Yochanan 4:10–14","answer":"At Yaakov’s well, Yeshua tells the Samaritan woman that the water He gives becomes a spring of water within, welling up to everlasting life.","key":["Yitzchak’s servants found a well of living water in the valley.","The wells of the fathers point to the water only יהוה gives."],"action":"Read Yochanan 4:5–14 beside Bereishit 26:17–22.","detail":"Notice whose well the conversation takes place at. Write one sentence on what that tells you about how the Brit Chadashah grows out of the Tanach."},{"q":"Which well of truth have I let others fill with earth?","ref":"26:15, 18","answer":"After Avraham died, the Philistines filled his wells with earth.","key":["What the fathers opened can be closed by neglect and hostility.","Reopening takes work, not nostalgia."],"action":"Clear one thing that has buried a truth you once held.","detail":"It may be an opinion you absorbed, a habit that crowded out study, or a voice you let speak louder than the Word. Remove or reduce it this week."},{"q":"Am I willing to move on from a quarrel instead of winning it?","ref":"26:20–22","answer":"Twice Yitzchak let a disputed well go and dug again.","key":["His answer to strife was another shovel, not another argument.","Rechovot came after he let go."],"action":"Step back from one argument over something that is not essential.","detail":"Tell the other person plainly that you are letting the matter go, and put your energy into something that builds instead."}],"closing":"The Philistines filled the wells. Yitzchak kept digging.","actionOfDay":"Choose one practice of faith that neglect has filled in, such as the Shabbat table, family prayer or reading the Torah portion. Restart it this week, and set the day and time now.","waSummary":"Yitzchak reopens his father’s wells and keeps digging past every quarrel until he finds a well no one disputes: Rechovot."},"af":{"title":"Hou Aan Grawe","blessing":"Boker Tov! Mag vandag se Aliyah ons die geduld gee om aan te hou grawe.","hook":"Yitzchak het aangehou grawe totdat יהוה ruimte gemaak het.","summary":"Yitzchak word baie groot, en die Filistyne is jaloers op hom; hulle het reeds die putte wat Avraham se dienaars gegrawe het, toegestop en met grond gevul. Avimeleg stuur hom weg, en Yitzchak vestig hom in die laagte van Gerar, waar hy sy vader se putte weer oopgrawe en hulle die name gee wat sy vader hulle gegee het. Sy dienaars kry ’n put met lewende water, maar die veewagters van Gerar eis dit op, en hy noem dit Esek en grawe ’n ander een; hulle twis ook oor dié een, en hy noem dit Sitnah. Hy trek verder en grawe ’n derde put waaroor niemand twis nie, en noem dit Rechovot, omdat יהוה vir hulle ruimte gemaak het om vrugbaar te wees in die land.","questions":[{"q":"Wat het Yitzchak gedoen met die putte wat die Filistyne toegestop het?","ref":"26:15, 18","answer":"Hy het hulle weer oopgegrawe en hulle dieselfde name gegee wat sy vader hulle gegee het.","key":["Hy het heropen wat sy vader oopgemaak het.","Hy het sy vader se name daarop behou."],"action":"Heropen een put wat jou vaders in die geloof gegrawe het.","detail":"Kies een gebruik wat aan jou oorgedra is en stil geword het, soos ’n seën aan tafel, ’n gebed of ’n Skrifgedeelte wat jy eens uit jou kop geken het. Herstel dit hierdie week."},{"q":"Hoekom het Yitzchak van Esek en Sitnah af verder getrek?","ref":"26:20–22","answer":"Elke keer wat die veewagters van Gerar die water opgeëis het, het hy die put na die twis vernoem en ’n ander een gegrawe, totdat hy een gekry het waaroor niemand getwis het nie.","key":["Esek beteken twis, Sitnah beteken vyandskap, en Rechovot beteken wye ruimtes.","Hy het nie vir elke put geveg nie. Die ruimte het gekom nadat hy verder getrek het."],"action":"Noem jou Esek en jou Sitnah.","detail":"Identifiseer een konflik waarna jy telkens terugkeer oor iets wat nie wesenlik is nie. Skryf neer wat jy sou wen as jy elders grawe."},{"q":"Hoe praat Yeshua van lewende water?","ref":"26:19; Yochanan 4:10–14","answer":"By Yaakov se put sê Yeshua vir die Samaritaanse vrou dat die water wat Hy gee, ’n fontein in haar word wat opborrel tot die ewige lewe.","key":["Yitzchak se dienaars het in die laagte ’n put met lewende water gekry.","Die putte van die vaders wys na die water wat net יהוה gee."],"action":"Lees Yochanan 4:5–14 saam met Bereishit 26:17–22.","detail":"Let op by wie se put die gesprek plaasvind. Skryf een sin oor wat dit jou leer oor hoe die Brit Chadashah uit die Tanach groei."},{"q":"Watter put van waarheid het ek toegelaat dat ander met grond vul?","ref":"26:15, 18","answer":"Nadat Avraham dood is, het die Filistyne sy putte met grond gevul.","key":["Wat die vaders oopgemaak het, kan deur verwaarlosing en vyandskap toegemaak word.","Om te heropen verg werk, nie nostalgie nie."],"action":"Ruim een ding op wat ’n waarheid begrawe het wat jy eens vasgehou het.","detail":"Dit kan ’n mening wees wat jy oorgeneem het, ’n gewoonte wat studie verdring het, of ’n stem wat jy harder as die Woord laat praat het. Verwyder of beperk dit hierdie week."},{"q":"Is ek bereid om van ’n twis af weg te stap eerder as om dit te wen?","ref":"26:20–22","answer":"Twee keer het Yitzchak ’n betwiste put laat gaan en weer gegrawe.","key":["Sy antwoord op twis was nog ’n graaf, nie nog ’n argument nie.","Rechovot het gekom nadat hy losgelaat het."],"action":"Tree terug uit een argument oor iets wat nie wesenlik is nie.","detail":"Sê vir die ander persoon reguit dat jy die saak laat gaan, en sit jou energie in iets wat opbou."}],"closing":"Die Filistyne het die putte gevul. Yitzchak het aangehou grawe.","actionOfDay":"Kies een geloofsgebruik wat verwaarlosing toegegooi het, soos die Shabbat-tafel, gesinsgebed of die lees van die Torahgedeelte. Begin dit hierdie week weer, en stel die dag en tyd nou vas.","waSummary":"Yitzchak grawe sy vader se putte weer oop en hou aan grawe ná elke twis, totdat hy ’n put kry waaroor niemand twis nie: Rechovot."}},{"date":"2026-11-11","parashah":"Toldot","year":"5787","aliyah":4,"ref":"Bereishit 26:23–29","en":{"title":"They Saw That יהוה Was With Him","blessing":"Boker Tov! May today’s Aliyah put worship before everything we build.","hook":"The men who drove Yitzchak away came back because they saw יהוה with him.","summary":"Yitzchak goes up to Beer-Sheva, and that night יהוה appears to him as the Elohim of Avraham his father and tells him not to fear, because He is with him and will bless him. Yitzchak builds an altar there, calls on the Name of יהוה, pitches his tent, and his servants dig a well. Avimelech comes from Gerar with his adviser and the commander of his army, and Yitzchak asks why they have come, since they hated him and sent him away. They answer that they have clearly seen that יהוה is with him, and ask for an oath and a covenant of peace between them.","questions":[{"q":"What did Yitzchak do after יהוה appeared to him at Beer-Sheva?","ref":"26:23–25","answer":"He built an altar, called on the Name of יהוה, pitched his tent there, and his servants dug a well.","key":["Altar first, tent second, well third.","Worship came before settling and before providing."],"action":"Put worship first in the order of your day.","detail":"Before you open messages or start work tomorrow, spend the first ten minutes in prayer and the Word."},{"q":"Why does יהוה say “Do not fear” at Beer-Sheva?","ref":"26:24","answer":"After the strife over the wells, יהוה tells Yitzchak that He is the Elohim of Avraham his father, that He is with him, and that He will bless him for Avraham’s sake.","key":["The promise is anchored in who יהוה has already been to his father.","Fear is answered with presence: I am with you."],"action":"Write down what יהוה has already been to those before you.","detail":"List three ways יהוה proved faithful to your parents, your teachers or the believers who brought you the truth. Read the list when fear rises."},{"q":"How does Yeshua describe the witness others see?","ref":"26:28; Mattityahu 5:14–16","answer":"Yeshua tells His disciples to let their light shine before others, so that they see their good works and glorify their Father in heaven.","key":["Avimelech’s men did not quote Yitzchak’s claims. They described what they had seen.","Testimony is what others observe, not only what we say."],"action":"Read Mattityahu 5:14–16 beside Bereishit 26:26–29.","detail":"Ask what the people around you could honestly say they have seen in your life this month."},{"q":"Can those who opposed me see יהוה with me?","ref":"26:27–28","answer":"Yitzchak’s former opponents said they had clearly seen that יהוה was with him.","key":["His conduct after being sent away became the evidence.","Hostility tests what people can see in me."],"action":"Treat someone who opposed you in a way that reflects יהוה.","detail":"Choose one person who has been against you. Do one fair, honest act toward them this week without expecting anything back."},{"q":"Will I listen to the people who hurt me?","ref":"26:27–29","answer":"Yitzchak named their hostility openly, and then listened to their proposal of peace.","key":["He did not pretend the past had not happened.","He still let them speak."],"action":"Hear out one person who wronged you, with the past named honestly.","detail":"If someone who hurt you is reaching out, agree to talk. Say plainly what happened, then listen fully before you answer."}],"closing":"Yitzchak built an altar before he dug a well.","actionOfDay":"Build your altar first today: before work, messages or plans, spend ten minutes in prayer and the Word, then begin the day.","waSummary":"At Beer-Sheva Yitzchak builds an altar, and the men who sent him away come to make peace because they saw יהוה with him."},"af":{"title":"Hulle Het Gesien dat יהוה by Hom Was","blessing":"Boker Tov! Mag vandag se Aliyah aanbidding vóór alles plaas wat ons bou.","hook":"Die manne wat Yitzchak weggejaag het, het teruggekom omdat hulle gesien het dat יהוה by hom is.","summary":"Yitzchak trek op na Be’er-Sheva, en daardie nag verskyn יהוה aan hom as die Elohim van sy vader Avraham en sê vir hom om nie te vrees nie, want Hy is by hom en sal hom seën. Yitzchak bou daar ’n altaar, roep die Naam van יהוה aan, slaan sy tent op, en sy dienaars grawe ’n put. Avimeleg kom van Gerar af saam met sy raadgewer en die bevelhebber van sy leër, en Yitzchak vra hoekom hulle gekom het, aangesien hulle hom gehaat en weggestuur het. Hulle antwoord dat hulle duidelik gesien het dat יהוה by hom is, en vra vir ’n eed en ’n vredesverbond tussen hulle.","questions":[{"q":"Wat het Yitzchak gedoen nadat יהוה by Be’er-Sheva aan hom verskyn het?","ref":"26:23–25","answer":"Hy het ’n altaar gebou, die Naam van יהוה aangeroep, sy tent daar opgeslaan, en sy dienaars het ’n put gegrawe.","key":["Eers die altaar, dan die tent, dan die put.","Aanbidding het gekom voordat hy hom gevestig en voorsien het."],"action":"Sit aanbidding eerste in die volgorde van jou dag.","detail":"Voordat jy môre boodskappe oopmaak of begin werk, bestee die eerste tien minute aan gebed en die Woord."},{"q":"Hoekom sê יהוה by Be’er-Sheva: “Moenie vrees nie”?","ref":"26:24","answer":"Ná die twis oor die putte sê יהוה vir Yitzchak dat Hy die Elohim van sy vader Avraham is, dat Hy by hom is, en dat Hy hom ter wille van Avraham sal seën.","key":["Die belofte is geanker in wie יהוה reeds vir sy vader was.","Vrees word met teenwoordigheid beantwoord: Ek is by jou."],"action":"Skryf neer wat יהוה reeds was vir dié wat voor jou gegaan het.","detail":"Lys drie maniere waarop יהוה getrou was aan jou ouers, jou leermeesters of die gelowiges wat die waarheid na jou gebring het. Lees die lys wanneer vrees opkom."},{"q":"Hoe beskryf Yeshua die getuienis wat ander sien?","ref":"26:28; Mattityahu 5:14–16","answer":"Yeshua sê vir sy dissipels om hulle lig voor ander te laat skyn, sodat hulle hul goeie werke kan sien en hul Vader in die hemel verheerlik.","key":["Avimeleg se manne het nie Yitzchak se aansprake aangehaal nie. Hulle het beskryf wat hulle gesien het.","Getuienis is wat ander waarneem, nie net wat ons sê nie."],"action":"Lees Mattityahu 5:14–16 saam met Bereishit 26:26–29.","detail":"Vra wat die mense om jou eerlik kan sê hulle hierdie maand in jou lewe gesien het."},{"q":"Kan dié wat my teengestaan het, sien dat יהוה by my is?","ref":"26:27–28","answer":"Yitzchak se voormalige teenstanders het gesê dat hulle duidelik gesien het dat יהוה by hom is.","key":["Sy optrede nadat hy weggestuur is, het die bewys geword.","Vyandigheid toets wat mense in my kan sien."],"action":"Behandel iemand wat jou teengestaan het op ’n manier wat יהוה weerspieël.","detail":"Kies een persoon wat teen jou was. Doen hierdie week een regverdige, eerlike daad teenoor hulle sonder om iets terug te verwag."},{"q":"Sal ek luister na die mense wat my seergemaak het?","ref":"26:27–29","answer":"Yitzchak het hulle vyandigheid openlik benoem en toe na hulle voorstel van vrede geluister.","key":["Hy het nie voorgegee dat die verlede nie gebeur het nie.","Hy het hulle steeds laat praat."],"action":"Luister na een persoon wat jou onreg aangedoen het, met die verlede eerlik benoem.","detail":"As iemand wat jou seergemaak het, uitreik, stem in om te praat. Sê reguit wat gebeur het, en luister dan volledig voordat jy antwoord."}],"closing":"Yitzchak het ’n altaar gebou voordat hy ’n put gegrawe het.","actionOfDay":"Bou vandag eers jou altaar: voor werk, boodskappe of planne, bestee tien minute aan gebed en die Woord, en begin dan die dag.","waSummary":"Yitzchak bou ’n altaar by Be’er-Sheva, en sy teenstanders kom vrede maak omdat יהוה by hom is."}},{"date":"2026-11-12","parashah":"Toldot","year":"5787","aliyah":5,"ref":"Bereishit 26:30–27:27","en":{"title":"The Voice and the Hands","blessing":"Boker Tov! May today’s Aliyah make our voice and our hands agree.","hook":"The voice was Yaakov’s; the hands were dressed as Esav’s.","summary":"Yitzchak makes a feast for Avimelech, they swear an oath of peace, and that same day his servants find water at Beer-Sheva. Esav marries two Hittite women, who are a grief to Yitzchak and Rivkah. When Yitzchak is old and his eyes are dim, he sends Esav to hunt and prepare a meal so that he may bless him; Rivkah overhears and tells Yaakov to bring two young goats so that she can prepare the meal and he can receive the blessing instead. Dressed in Esav’s clothes, with goat skins on his hands and neck, Yaakov tells his father he is Esav; Yitzchak hesitates over the voice, but after touching, eating and smelling Esav’s garments, he blesses him.","questions":[{"q":"What did Yaakov say when his father asked who he was?","ref":"27:18–20","answer":"He said he was Esav the firstborn, and when asked how he found game so quickly, he said יהוה his father’s Elohim had brought it to him.","key":["He used the Name of יהוה to support a lie.","The deception reached even his words about Elohim."],"action":"Check your speech about Elohim today.","detail":"Notice each time you say that יהוה led, opened or provided. Make sure it is true, and not a way of covering your own plan."},{"q":"Why did Yitzchak’s doubt not stop the blessing?","ref":"27:21–27","answer":"He noticed that the voice was Yaakov’s, but the feel of the hands, the taste of the meal and the smell of the garments persuaded him.","key":["He trusted what he could touch, taste and smell over what he heard.","Every step of the plan worked through the senses."],"action":"Test one decision by what you hear, not only by what feels right.","detail":"Before you decide something important this week, write down what the Word actually says about it, and let that weigh more than your impression."},{"q":"What does the Haftarah ask about a son’s honour?","ref":"27:19; Malachi 1:6","answer":"In the Haftarah, יהוה says that a son honours his father, and asks: if I am a Father, where is My honour?","key":["Yaakov came to his father in another man’s name and another man’s clothes.","Malachi asks whether we bring honest honour to our Father in heaven."],"action":"Read Malachi 1:6–8 beside Bereishit 27:18–24.","detail":"Write down one way you could honour your Father in heaven more honestly this week."},{"q":"Have I used the Name of יהוה to cover my own plan?","ref":"27:20","answer":"Yaakov credited יהוה with a meal that came from his mother’s kitchen.","key":["Spiritual language can dress up a deception.","I need to check whether I say “יהוה led me” about decisions I engineered."],"action":"Name one decision you have dressed in spiritual language.","detail":"Write it down honestly, as it really happened. If you told others that יהוה led you, consider whether you need to correct that."},{"q":"Whose voice am I obeying?","ref":"27:8, 11–13","answer":"Rivkah twice told Yaakov to obey her voice, and took any curse upon herself; Yaakov objected only that he might be caught.","key":["Yaakov raised the risk. He did not raise the question of right and wrong.","His concern was being caught, not being wrong."],"action":"Ask whether a plan is right, not only whether it will work.","detail":"Before you follow anyone’s plan this week, however close they are to you, ask aloud: is this right before יהוה?"}],"closing":"Yaakov feared being caught more than being wrong.","actionOfDay":"Before you agree to a plan today, ask one question aloud: is this right before יהוה, or only likely to work? If it is only the second, stop.","waSummary":"Dressed in Esav’s clothes, Yaakov tells his blind father he is Esav, and Yitzchak blesses him."},"af":{"title":"Die Stem en die Hande","blessing":"Boker Tov! Mag vandag se Aliyah ons stem en ons hande laat ooreenstem.","hook":"Die stem was Yaakov s’n; die hande was soos Esav s’n aangetrek.","summary":"Yitzchak berei ’n maaltyd vir Avimeleg, hulle sweer ’n eed van vrede, en dieselfde dag kry sy dienaars water by Be’er-Sheva. Esav trou met twee Hetitiese vroue, wat vir Yitzchak en Rivkah ’n bitter smart is. Wanneer Yitzchak oud is en sy oë dof geword het, stuur hy Esav om te gaan jag en ’n maaltyd te berei sodat hy hom kan seën; Rivkah hoor dit en sê vir Yaakov om twee bokkies te bring sodat sy die maaltyd kan berei en hy eerder die seën kan ontvang. Aangetrek in Esav se klere, met bokvelle oor sy hande en nek, sê Yaakov vir sy vader dat hy Esav is; Yitzchak huiwer oor die stem, maar nadat hy hom gevoel, geëet en Esav se klere geruik het, seën hy hom.","questions":[{"q":"Wat het Yaakov gesê toe sy vader vra wie hy is?","ref":"27:18–20","answer":"Hy het gesê hy is Esav, die eersgeborene, en toe gevra word hoe hy die wild so gou gekry het, het hy gesê dat יהוה, sy vader se Elohim, dit na hom gebring het.","key":["Hy het die Naam van יהוה gebruik om ’n leuen te stut.","Die misleiding het selfs sy woorde oor Elohim bereik."],"action":"Kontroleer vandag jou woorde oor Elohim.","detail":"Let op elke keer wat jy sê dat יהוה gelei, oopgemaak of voorsien het. Maak seker dit is waar, en nie ’n manier om jou eie plan te bedek nie."},{"q":"Hoekom het Yitzchak se twyfel nie die seën gekeer nie?","ref":"27:21–27","answer":"Hy het opgemerk dat die stem Yaakov s’n was, maar die gevoel van die hande, die smaak van die maaltyd en die reuk van die klere het hom oortuig.","key":["Hy het vertrou op wat hy kon voel, proe en ruik, bo wat hy gehoor het.","Elke stap van die plan het deur die sintuie gewerk."],"action":"Toets een besluit aan wat jy hoor, nie net aan wat reg voel nie.","detail":"Voordat jy hierdie week iets belangriks besluit, skryf neer wat die Woord werklik daaroor sê, en laat dit swaarder weeg as jou indruk."},{"q":"Wat vra die Haftarah oor ’n seun se eer?","ref":"27:19; Maleagi 1:6","answer":"In die Haftarah sê יהוה dat ’n seun sy vader eer, en vra: as Ek ’n Vader is, waar is my eer?","key":["Yaakov het na sy vader gekom in ’n ander man se naam en ’n ander man se klere.","Maleagi vra of ons eerlike eer aan ons Vader in die hemel bring."],"action":"Lees Maleagi 1:6–8 saam met Bereishit 27:18–24.","detail":"Skryf een manier neer waarop jy jou Vader in die hemel hierdie week eerliker kan eer."},{"q":"Het ek die Naam van יהוה gebruik om my eie plan te bedek?","ref":"27:20","answer":"Yaakov het יהוה die eer gegee vir ’n maaltyd wat uit sy moeder se kombuis gekom het.","key":["Geestelike taal kan ’n misleiding aantrek.","Ek moet nagaan of ek sê “יהוה het my gelei” oor besluite wat ek self bewerkstellig het."],"action":"Noem een besluit wat jy in geestelike taal geklee het.","detail":"Skryf dit eerlik neer, soos dit werklik gebeur het. As jy vir ander gesê het dat יהוה jou gelei het, oorweeg of jy dit moet regstel."},{"q":"Na wie se stem luister ek?","ref":"27:8, 11–13","answer":"Rivkah het Yaakov twee keer gesê om na haar stem te luister en enige vloek op haarself geneem; Yaakov se enigste beswaar was dat hy dalk uitgevang sou word.","key":["Yaakov het die risiko genoem. Hy het nie die vraag van reg en verkeerd genoem nie.","Sy kommer was om uitgevang te word, nie om verkeerd te wees nie."],"action":"Vra of ’n plan reg is, nie net of dit sal werk nie.","detail":"Voordat jy hierdie week iemand se plan volg, hoe na hulle ook al aan jou is, vra hardop: is dit reg voor יהוה?"}],"closing":"Yaakov was banger om uitgevang te word as om verkeerd te wees.","actionOfDay":"Voordat jy vandag tot ’n plan instem, vra hardop een vraag: is dit reg voor יהוה, of sal dit net waarskynlik werk? As dit net die tweede is, stop.","waSummary":"In Esav se klere sê Yaakov vir sy blinde vader dat hy Esav is, en Yitzchak seën hom."}},{"date":"2026-11-13","parashah":"Toldot","year":"5787","aliyah":6,"ref":"Bereishit 27:28–28:4","en":{"title":"A Great and Bitter Cry","blessing":"Boker Tov! May today’s Aliyah teach us to value the blessing before it is gone.","hook":"Esav wept for the blessing after he had despised the birthright.","summary":"Yitzchak blesses Yaakov with the dew of heaven, the richness of the earth and rule over his brothers. As soon as Yaakov leaves, Esav arrives with his meal; Yitzchak trembles greatly but confirms that the one he blessed will be blessed, and Esav cries out with a great and bitter cry and receives only a lesser word. Esav resolves in his heart to kill Yaakov once the days of mourning for their father come, so Rivkah sends Yaakov to her brother Lavan in Charan. Yitzchak calls Yaakov, commands him not to take a wife from the daughters of Canaan, and blesses him with the blessing of Avraham.","questions":[{"q":"What did Yitzchak do when he realised what had happened?","ref":"27:30–33","answer":"He trembled exceedingly, and then confirmed that the one he had blessed would indeed be blessed.","key":["He did not take the blessing back.","Even in shock, he let his spoken word stand."],"action":"Keep one promise you are tempted to withdraw.","detail":"Think of a commitment you made that has become inconvenient. Honour it this week."},{"q":"Why could Esav not get the first blessing back?","ref":"27:34–40","answer":"Yitzchak said he had already made Yaakov lord over him and sustained him with grain and wine; what remained for Esav was a lesser word.","key":["Esav cried out with a great and bitter cry.","His tears came after his choices, not before them."],"action":"Grieve your losses honestly, but learn from them before the next choice.","detail":"Name one consequence you are living with now. Write down the choice that led to it, and what you will do differently next time."},{"q":"How does Paul read the older serving the younger?","ref":"25:23; Malachi 1:2–3; Romans 9:10–13","answer":"Paul joins Bereishit 25:23 and Malachi 1:2–3 to show that the choice of Yaakov over Esav rests on the purpose of Elohim who calls, not on works.","key":["The older serving the younger was spoken before the twins were born.","Malachi, this week’s Haftarah, repeats it centuries later."],"action":"Read Romans 9:6–16 with Bereishit 25:21–23 and Malachi 1:2–3 open.","detail":"Mark where Paul quotes the Tanach. Write one sentence on what this teaches you about the calling of Elohim."},{"q":"Is my hatred waiting for a better time?","ref":"27:41","answer":"Esav decided in his heart to kill Yaakov after the days of mourning for his father.","key":["His hatred had a timetable.","Postponed revenge is still revenge."],"action":"Cancel one plan to “deal with someone later.”","detail":"Name the person you have been waiting to get even with. Bring the matter before יהוה in prayer and release the plan."},{"q":"What did Yitzchak require of Yaakov when he sent him with the blessing of Avraham?","ref":"28:1–4","answer":"He commanded Yaakov not to take a wife from the daughters of Canaan but from his mother’s family, and blessed him with the blessing of Avraham.","key":["The blessing came with a command about whom to marry.","The covenant shapes ordinary choices like marriage."],"action":"Bring one major relationship decision under the instruction of Scripture.","detail":"If you or someone you guide is facing a decision about marriage or a close partnership, read what the Torah and the Brit Chadashah say about it before going further."}],"closing":"Tears could not buy back what appetite had sold.","actionOfDay":"Name the person you have been planning to “deal with later.” Before Shabbat begins tonight, release that plan before יהוה in prayer and take one step toward peace.","waSummary":"Esav arrives too late and cries out bitterly for the blessing, then plans to kill Yaakov, who is sent away to Lavan."},"af":{"title":"’n Groot en Bitter Geroep","blessing":"Boker Tov! Mag vandag se Aliyah ons leer om die seën te waardeer voordat dit weg is.","hook":"Esav het oor die seën gehuil nadat hy die eersgeboortereg verag het.","summary":"Yitzchak seën Yaakov met die dou van die hemel, die vettigheid van die aarde en heerskappy oor sy broers. Net toe Yaakov uitgaan, kom Esav met sy maaltyd; Yitzchak bewe hewig, maar bevestig dat die een wat hy geseën het, geseën sal wees, en Esav skreeu ’n groot en bitter geroep en ontvang net ’n mindere woord. Esav besluit in sy hart om Yaakov dood te maak sodra die dae van rou oor hulle vader aanbreek, en daarom stuur Rivkah vir Yaakov na haar broer Lavan in Charan. Yitzchak roep Yaakov, beveel hom om nie ’n vrou uit die dogters van Kanaän te neem nie, en seën hom met die seën van Avraham.","questions":[{"q":"Wat het Yitzchak gedoen toe hy besef wat gebeur het?","ref":"27:30–33","answer":"Hy het hewig gebewe, en toe bevestig dat die een wat hy geseën het, inderdaad geseën sal wees.","key":["Hy het die seën nie teruggeneem nie.","Selfs in skok het hy sy gesproke woord laat staan."],"action":"Hou een belofte wat jy in die versoeking is om terug te trek.","detail":"Dink aan ’n verbintenis wat jy gemaak het en wat ongerieflik geword het. Kom dit hierdie week na."},{"q":"Hoekom kon Esav nie die eerste seën terugkry nie?","ref":"27:34–40","answer":"Yitzchak het gesê dat hy Yaakov reeds heer oor hom gemaak en hom met koring en wyn versorg het; wat vir Esav oorgebly het, was ’n mindere woord.","key":["Esav het ’n groot en bitter geroep uitgeskreeu.","Sy trane het ná sy keuses gekom, nie voor hulle nie."],"action":"Rou eerlik oor jou verliese, maar leer daaruit voor die volgende keuse.","detail":"Noem een gevolg waarmee jy nou saamleef. Skryf die keuse neer wat daartoe gelei het, en wat jy volgende keer anders sal doen."},{"q":"Hoe lees Paulus dat die oudste die jongste sal dien?","ref":"25:23; Maleagi 1:2–3; Romeine 9:10–13","answer":"Paulus verbind Bereishit 25:23 en Maleagi 1:2–3 om te wys dat die keuse van Yaakov bo Esav berus op die voorneme van Elohim wat roep, nie op werke nie.","key":["Dat die oudste die jongste sal dien, is gespreek voordat die tweeling gebore is.","Maleagi, hierdie week se Haftarah, herhaal dit eeue later."],"action":"Lees Romeine 9:6–16 met Bereishit 25:21–23 en Maleagi 1:2–3 oop.","detail":"Merk waar Paulus die Tanach aanhaal. Skryf een sin oor wat dit jou leer oor die roeping van Elohim."},{"q":"Wag my haat vir ’n beter tyd?","ref":"27:41","answer":"Esav het in sy hart besluit om Yaakov dood te maak ná die dae van rou oor sy vader.","key":["Sy haat het ’n tydrooster gehad.","Uitgestelde wraak is steeds wraak."],"action":"Kanselleer een plan om iemand “later te hanteer.”","detail":"Noem die persoon met wie jy gewag het om gelyk te kry. Bring die saak in gebed voor יהוה en laat die plan los."},{"q":"Wat het Yitzchak van Yaakov vereis toe hy hom met die seën van Avraham weggestuur het?","ref":"28:1–4","answer":"Hy het Yaakov beveel om nie ’n vrou uit die dogters van Kanaän te neem nie, maar uit sy moeder se familie, en hom met die seën van Avraham geseën.","key":["Die seën het gekom met ’n gebod oor met wie om te trou.","Die verbond vorm gewone keuses soos die huwelik."],"action":"Bring een groot verhoudingsbesluit onder die onderrig van die Skrif.","detail":"As jy of iemand wat jy begelei, voor ’n besluit oor ’n huwelik of ’n nou vennootskap staan, lees wat die Torah en die Brit Chadashah daaroor sê voordat julle verder gaan."}],"closing":"Trane kon nie terugkoop wat aptyt verkoop het nie.","actionOfDay":"Noem die persoon wat jy van plan was om “later te hanteer.” Laat daardie plan voor Shabbat vanaand begin in gebed voor יהוה los, en neem een tree na vrede.","waSummary":"Esav kom te laat en skreeu bitterlik om die seën, en beplan dan om Yaakov dood te maak, wat na Lavan weggestuur word."}},{"date":"2026-11-14","parashah":"Toldot","year":"5787","aliyah":7,"ref":"Bereishit 28:5–9","en":{"title":"Pleasing or Obeying","blessing":"Boker Tov and Shabbat Shalom! May today’s Aliyah teach us to obey, not merely to please.","hook":"Esav tried to please his father by adding a wife instead of changing his ways.","summary":"Yitzchak sends Yaakov away, and he goes to Paddan-Aram, to Lavan son of Betuel the Aramean, the brother of Rivkah. Esav sees that his father has blessed Yaakov and charged him not to take a Canaanite wife, and that Yaakov obeyed his father and mother and went. Realising that the daughters of Canaan displease his father, Esav goes to Yishmael and takes Machalat, Yishmael’s daughter, as a wife, in addition to the wives he already has.","questions":[{"q":"What did Yaakov do after his father’s charge?","ref":"28:5, 7","answer":"He obeyed his father and his mother and went to Paddan-Aram.","key":["The text names his obedience to both parents.","He left home with the blessing and the instruction."],"action":"Carry out one instruction from a parent or elder that agrees with Scripture.","detail":"Think of counsel you received from a parent, elder or teacher that you know is right but have not acted on. Take the first step this week."},{"q":"What did Esav learn from watching Yaakov, and what did he do with it?","ref":"28:6–9","answer":"He saw that the daughters of Canaan displeased his father, so he took a daughter of Yishmael as a wife, in addition to the wives he already had.","key":["He observed the right lesson and applied it the wrong way.","He added to his choices instead of turning from them."],"action":"Look for the change behind the lesson, not only the gesture.","detail":"Think of a correction you received recently. Ask what real change it calls for, not just what would look better."},{"q":"What does the Haftarah say about offerings that cost little?","ref":"28:9; Malachi 1:7–8","answer":"In the Haftarah, יהוה rebukes the priests for bringing blind and lame animals as offerings, and asks whether their governor would accept such a gift.","key":["Esav also tried to please with something that cost him little.","Pleasing Elohim is not a matter of adding a gesture, but of giving what He asked."],"action":"Read Malachi 1:6–11 beside Bereishit 28:6–9.","detail":"Write down one area where you give יהוה what is left over instead of what is first and best."},{"q":"Am I trying to please with additions instead of repentance?","ref":"28:9","answer":"Esav took Machalat in addition to the Hittite wives who had grieved his parents.","key":["His solution left the original problem in place.","I can add a religious habit without letting go of what grieves Elohim."],"action":"Name one thing you have added to ease your conscience.","detail":"Then name what it was meant to cover. Bring that real issue before יהוה honestly."},{"q":"Will I go where obedience sends me?","ref":"28:5","answer":"Yitzchak sent Yaakov away, and Yaakov went.","key":["Obedience sometimes means leaving what is familiar.","He went with the blessing and the charge his father gave him."],"action":"Take one step this week in the direction obedience has been pointing you.","detail":"Name the move, conversation or commitment you know you are called to. Set a date for the first step."}],"deeper":"The Haftarah, Malachi 1:1–2:7, opens where this Parashah ends: יהוה declares that He loved Yaakov and rejected Esav, and that Edom will build but He will tear down (Malachi 1:2–4). It then rebukes priests who despise His Name with blemished offerings (1:6–8), the same failing as Esav, who despised his birthright (Bereishit 25:34), and holds up the covenant with Levi, in whose mouth was the Torah of truth (2:5–7). Paul brings Bereishit 25:23 and Malachi 1:2–3 together in Romans 9:10–13 to show that the choice rests on the purpose of Elohim who calls. Hebrews 12:16–17 turns the whole Parashah into a warning: do not be like Esav, who sold his birthright for a single meal.","closing":"Esav added a wife. Yaakov obeyed and went.","actionOfDay":"This Shabbat, name one thing you have added to your life to ease your conscience instead of turning from what grieves יהוה. Write down the real step of repentance, and take it on the first day of the week.","waSummary":"Yaakov obeys his parents and leaves for Paddan-Aram, while Esav adds a daughter of Yishmael to his wives to please his father."},"af":{"title":"Behaag of Gehoorsaam","blessing":"Boker Tov en Shabbat Shalom! Mag vandag se Aliyah ons leer om te gehoorsaam, nie net om te behaag nie.","hook":"Esav het probeer om sy vader te behaag deur ’n vrou by te voeg in plaas daarvan om sy weë te verander.","summary":"Yitzchak stuur Yaakov weg, en hy gaan na Paddan-Aram, na Lavan, die seun van Betuél die Arameër, die broer van Rivkah. Esav sien dat sy vader Yaakov geseën het en hom beveel het om nie ’n Kanaänitiese vrou te neem nie, en dat Yaakov na sy vader en moeder geluister en gegaan het. Wanneer Esav besef dat die dogters van Kanaän sy vader mishaag, gaan hy na Yishmael en neem Machalat, Yishmael se dogter, as vrou, bo en behalwe die vroue wat hy reeds het.","questions":[{"q":"Wat het Yaakov gedoen ná sy vader se opdrag?","ref":"28:5, 7","answer":"Hy het na sy vader en sy moeder geluister en na Paddan-Aram gegaan.","key":["Die teks noem sy gehoorsaamheid aan albei ouers.","Hy het die huis verlaat met die seën en die opdrag."],"action":"Voer een opdrag uit van ’n ouer of ouderling wat met die Skrif ooreenstem.","detail":"Dink aan raad wat jy van ’n ouer, ouderling of leermeester ontvang het wat jy weet reg is, maar waarop jy nog nie opgetree het nie. Neem hierdie week die eerste tree."},{"q":"Wat het Esav geleer deur na Yaakov te kyk, en wat het hy daarmee gedoen?","ref":"28:6–9","answer":"Hy het gesien dat die dogters van Kanaän sy vader mishaag, en daarom het hy ’n dogter van Yishmael as vrou geneem, bo en behalwe die vroue wat hy reeds gehad het.","key":["Hy het die regte les waargeneem en dit verkeerd toegepas.","Hy het by sy keuses bygevoeg in plaas daarvan om van hulle af weg te draai."],"action":"Soek die verandering agter die les, nie net die gebaar nie.","detail":"Dink aan ’n teregwysing wat jy onlangs ontvang het. Vra watter werklike verandering dit vra, nie net wat beter sou lyk nie."},{"q":"Wat sê die Haftarah oor offers wat min kos?","ref":"28:9; Maleagi 1:7–8","answer":"In die Haftarah bestraf יהוה die priesters omdat hulle blinde en kreupel diere as offers bring, en vra of hulle goewerneur so ’n geskenk sou aanvaar.","key":["Esav het ook probeer behaag met iets wat hom min gekos het.","Om Elohim te behaag gaan nie oor ’n gebaar wat bygevoeg word nie, maar oor gee wat Hy gevra het."],"action":"Lees Maleagi 1:6–11 saam met Bereishit 28:6–9.","detail":"Skryf een terrein neer waar jy vir יהוה gee wat oorbly, in plaas van wat eerste en beste is."},{"q":"Probeer ek met byvoegings behaag in plaas van bekering?","ref":"28:9","answer":"Esav het Machalat geneem bo en behalwe die Hetitiese vroue wat sy ouers smart aangedoen het.","key":["Sy oplossing het die oorspronklike probleem laat staan.","Ek kan ’n godsdienstige gewoonte byvoeg sonder om los te laat wat Elohim bedroef."],"action":"Noem een ding wat jy bygevoeg het om jou gewete te sus.","detail":"Noem dan wat dit moes bedek. Bring daardie werklike saak eerlik voor יהוה."},{"q":"Sal ek gaan waarheen gehoorsaamheid my stuur?","ref":"28:5","answer":"Yitzchak het Yaakov weggestuur, en Yaakov het gegaan.","key":["Gehoorsaamheid beteken soms om te verlaat wat bekend is.","Hy het gegaan met die seën en die opdrag wat sy vader hom gegee het."],"action":"Neem hierdie week een tree in die rigting waarheen gehoorsaamheid jou wys.","detail":"Noem die skuif, gesprek of verbintenis waartoe jy weet jy geroep is. Stel ’n datum vir die eerste tree."}],"deeper":"Die Haftarah, Maleagi 1:1–2:7, begin waar hierdie Parashah eindig: יהוה verklaar dat Hy Yaakov liefgehad en Esav verwerp het, en dat Edom sal bou maar Hy sal afbreek (Maleagi 1:2–4). Daarna bestraf Hy die priesters wat sy Naam verag met gebrekkige offers (1:6–8), dieselfde tekortkoming as Esav, wat sy eersgeboortereg verag het (Bereishit 25:34), en hou Hy die verbond met Levi voor, in wie se mond die Torah van waarheid was (2:5–7). Paulus bring Bereishit 25:23 en Maleagi 1:2–3 saam in Romeine 9:10–13 om te wys dat die keuse berus op die voorneme van Elohim wat roep. Hebreërs 12:16–17 maak van die hele Parashah ’n waarskuwing: moenie wees soos Esav nie, wat sy eersgeboortereg vir een maaltyd verkoop het.","closing":"Esav het ’n vrou bygevoeg. Yaakov het gehoorsaam en gegaan.","actionOfDay":"Noem hierdie Shabbat een ding wat jy in jou lewe bygevoeg het om jou gewete te sus, in plaas daarvan om weg te draai van wat יהוה bedroef. Skryf die werklike tree van bekering neer, en neem dit op die eerste dag van die week.","waSummary":"Yaakov gehoorsaam sy ouers en vertrek, terwyl Esav nog ’n vrou neem om sy vader te behaag."}},{"date":"2026-11-15","parashah":"Vayetze","year":"5787","aliyah":1,"ref":"Bereishit 28:10–22","en":{"title":"The Place He Did Not Know","blessing":"Shavuah Tov! May this week’s first Aliyah open our eyes to where יהוה already stands with us.","hook":"Yaakov lay down on a stone at the gate of heaven and did not know it until יהוה spoke.","summary":"Yaakov leaves Beer-Sheva for Charan, and at sunset he takes a stone for his head and sleeps. He dreams of a ladder set on the earth with its top reaching heaven, with messengers of Elohim going up and down on it, and יהוה standing above it. יהוה confirms to him the land and the seed promised to Avraham and Yitzchak, and promises to be with him, to keep him wherever he goes and to bring him back. Yaakov wakes, says that יהוה is in this place and he did not know it, sets up the stone as a pillar, anoints it, names the place Beit-El and vows to give a tenth of all that Elohim gives him.","waSummary":"Running from Esav, Yaakov sleeps on a stone and dreams of a ladder to heaven, and יהוה promises to be with him and bring him back.","questions":[{"q":"What did Yaakov see in his dream?","ref":"28:12–13","answer":"He saw a ladder set on the earth and reaching to heaven, with messengers of Elohim going up and down on it, and יהוה standing above it.","key":["Heaven was not closed to a man running for his life.","יהוה did not stand at a distance. He spoke first, and He spoke His Name."],"action":"Write down where you are “running” right now.","detail":"Then write beside it: יהוה stands above this place too. Read Bereishit 28:15 aloud over that situation."},{"q":"What did יהוה promise Yaakov before Yaakov promised anything?","ref":"28:14–15","answer":"יהוה promised to be with him, to keep him wherever he goes, to bring him back to the land and not to leave him until He had done what He had spoken.","key":["The promise came before the vow. Grace led and obedience answered.","Yaakov left home with nothing in his hands but a promise from יהוה."],"action":"Memorise Bereishit 28:15 today.","detail":"Write it on a card and keep it with you. Read it each time you feel alone this week."},{"q":"How does Yeshua connect himself to Yaakov’s ladder?","ref":"28:12; Yochanan 1:47–51","answer":"Yeshua tells Natan’el that he will see heaven opened and the messengers of Elohim going up and coming down on the Son of Adam.","key":["Yeshua takes Yaakov’s dream and places himself where the ladder stood.","He speaks these words to a Yisra’eli in whom there is no deceit, the opposite of the old Yaakov."],"action":"Read Yochanan 1:43–51 beside Bereishit 28:10–17.","detail":"Mark every word the two passages share. Write one sentence on what Yeshua is saying about himself."},{"q":"Where is יהוה present in my life while I do not know it?","ref":"28:16–17","answer":"Yaakov woke up and said that יהוה was in this place and he had not known it, and he was afraid.","key":["Yaakov’s ignorance did not cancel יהוה’s presence.","The place he thought was just a stopover was the house of Elohim."],"action":"Name one ordinary place you pass through every day.","detail":"Your car, kitchen or workplace. Before you leave it today, stop for one minute and acknowledge that יהוה is there."},{"q":"What did Yaakov commit to give back?","ref":"28:20–22","answer":"He vowed that the stone would be a house of Elohim and that he would give a tenth of everything Elohim gives him.","key":["Yaakov had nothing yet, but he decided ahead of time what belonged to יהוה.","A vow made with empty hands is a confession that everything will come from Him."],"action":"Decide today what portion you will set apart for יהוה.","detail":"Do not wait for the next income. Write down the amount or the time you will give, and when."}],"closing":"He slept on a stone and woke at the gate of heaven.","actionOfDay":"Before tonight, write Bereishit 28:15 on a card, put it where you will see it every morning this week, and read it aloud once today over the situation you are most anxious about."},"af":{"title":"Die Plek Wat Hy Nie Geken Het Nie","blessing":"Shavuah Tov! Mag hierdie week se eerste Aliyah ons oë oopmaak vir waar יהוה reeds by ons staan.","hook":"Yaakov het op ’n klip by die poort van die hemel gaan lê en dit nie geweet nie, totdat יהוה gepraat het.","summary":"Yaakov vertrek uit Beer-Sheva na Charan, en met sononder neem hy ’n klip vir sy kop en gaan slaap. Hy droom van ’n leer wat op die aarde staan met sy bopunt tot in die hemel, met boodskappers van Elohim wat daarop op- en afklim, en יהוה wat daarbo staan. יהוה bevestig aan hom die land en die nageslag wat aan Avraham en Yitzchak beloof is, en belowe om by hom te wees, hom te bewaar oral waar hy gaan en hom terug te bring. Yaakov word wakker, sê dat יהוה op hierdie plek is en hy het dit nie geweet nie, rig die klip as ’n gedenksteen op, salf dit, noem die plek Beit-El en belowe om ’n tiende te gee van alles wat Elohim hom gee.","waSummary":"Op die vlug vir Esav slaap Yaakov op ’n klip en droom van ’n leer tot in die hemel, en יהוה belowe om by hom te wees en hom terug te bring.","questions":[{"q":"Wat het Yaakov in sy droom gesien?","ref":"28:12–13","answer":"Hy het ’n leer gesien wat op die aarde staan en tot in die hemel reik, met boodskappers van Elohim wat daarop op- en afklim, en יהוה wat daarbo staan.","key":["Die hemel was nie gesluit vir ’n man wat vir sy lewe vlug nie.","יהוה het nie op ’n afstand gebly nie. Hy het eerste gepraat, en Hy het Sy Naam genoem."],"action":"Skryf neer waarvoor jy nou op die vlug is.","detail":"Skryf dan langsaan: יהוה staan ook bo hierdie plek. Lees Bereishit 28:15 hardop oor daardie situasie."},{"q":"Wat het יהוה aan Yaakov belowe voordat Yaakov enigiets belowe het?","ref":"28:14–15","answer":"יהוה het belowe om by hom te wees, hom te bewaar oral waar hy gaan, hom na die land terug te bring en hom nie te verlaat voordat Hy gedoen het wat Hy gesê het nie.","key":["Die belofte het voor die gelofte gekom. Genade het gelei en gehoorsaamheid het geantwoord.","Yaakov het die huis verlaat met niks in sy hande nie behalwe ’n belofte van יהוה."],"action":"Leer Bereishit 28:15 vandag uit jou kop.","detail":"Skryf dit op ’n kaartjie en hou dit by jou. Lees dit elke keer wanneer jy hierdie week alleen voel."},{"q":"Hoe verbind Yeshua homself aan Yaakov se leer?","ref":"28:12; Yochanan 1:47–51","answer":"Yeshua sê vir Natan’el dat hy die hemel oop sal sien en die boodskappers van Elohim wat op die Seun van Adam opklim en afkom.","key":["Yeshua neem Yaakov se droom en plaas homself waar die leer gestaan het.","Hy sê dit vir ’n Yisra’eliet in wie daar geen bedrog is nie, die teenoorgestelde van die ou Yaakov."],"action":"Lees Yochanan 1:43–51 saam met Bereishit 28:10–17.","detail":"Merk elke woord wat die twee gedeeltes deel. Skryf een sin oor wat Yeshua hier oor homself sê."},{"q":"Waar is יהוה in my lewe teenwoordig sonder dat ek dit weet?","ref":"28:16–17","answer":"Yaakov het wakker geword en gesê dat יהוה op hierdie plek is en hy het dit nie geweet nie, en hy het bang geword.","key":["Yaakov se onkunde het יהוה se teenwoordigheid nie gekanselleer nie.","Die plek wat hy as net ’n oornagplek beskou het, was die huis van Elohim."],"action":"Noem een gewone plek waardeur jy elke dag gaan.","detail":"Jou motor, jou kombuis of jou werkplek. Voordat jy dit vandag verlaat, staan een minuut stil en erken dat יהוה daar is."},{"q":"Wat het Yaakov belowe om terug te gee?","ref":"28:20–22","answer":"Hy het belowe dat die klip ’n huis van Elohim sal wees en dat hy ’n tiende sal gee van alles wat Elohim hom gee.","key":["Yaakov het nog niks gehad nie, maar hy het vooraf besluit wat aan יהוה behoort.","’n Gelofte met leë hande is ’n belydenis dat alles van Hom sal kom."],"action":"Besluit vandag watter deel jy vir יהוה gaan afsonder.","detail":"Moenie wag vir die volgende inkomste nie. Skryf die bedrag of die tyd neer wat jy gaan gee, en wanneer."}],"closing":"Hy het op ’n klip geslaap en by die poort van die hemel wakker geword.","actionOfDay":"Skryf voor vanaand Bereishit 28:15 op ’n kaartjie, sit dit waar jy dit elke oggend hierdie week sal sien, en lees dit vandag een keer hardop oor die situasie waaroor jy die meeste bekommerd is."}},{"date":"2026-11-16","parashah":"Vayetze","year":"5787","aliyah":2,"ref":"Bereishit 29:1–17","en":{"title":"The Stone on the Well","blessing":"Boker Tov! May today’s Aliyah move us from waiting for others to doing what is in front of us.","hook":"The shepherds said the stone could not be moved until all the flocks were gathered; Yaakov saw Rachel and rolled it away.","summary":"Yaakov comes to the land of the people of the east and finds a well in a field, with flocks lying beside it and a large stone over its mouth. The shepherds of Charan tell him they know Lavan, that he is well, and that his daughter Rachel is coming with the sheep; they say they cannot water the flocks until all are gathered and the stone is rolled away. When Yaakov sees Rachel, he rolls the stone from the well, waters Lavan’s flock, kisses Rachel and weeps, and tells her he is Rivkah’s son. Lavan runs to meet him, brings him home and calls him his bone and his flesh, and after a month asks what his wages should be; Lavan has two daughters, Leah the elder, whose eyes were weak, and Rachel, who was beautiful.","waSummary":"At a well in Charan, Yaakov rolls away the stone, waters Lavan’s flock and meets Rachel, and Lavan takes him into his house.","questions":[{"q":"What did Yaakov do when he saw Rachel?","ref":"29:9–11","answer":"He went near, rolled the stone from the mouth of the well, watered the flock of Lavan, kissed Rachel and lifted up his voice and wept.","key":["Yaakov’s first act in Charan was service, not talk.","The man who left home with a stone under his head now lifts a stone off a well."],"action":"Do one task today that others are waiting for someone else to do.","detail":"Look for the “stone on the well” at home, at work or in your congregation, the job everyone sees and nobody starts. Start it."},{"q":"What changed when Lavan asked about wages?","ref":"29:14–15","answer":"Lavan called Yaakov his bone and his flesh, and after a month he asked him what his wages should be.","key":["The welcome of a relative turned into the terms of an employer.","Lavan’s question sets the tone for the next twenty years."],"action":"Notice where a relationship has quietly become a transaction.","detail":"Think of one person you mainly deal with in terms of what they give or cost you. Do one thing for them this week that asks nothing in return."},{"q":"How does Yeshua answer the question of who is greater than Yaakov?","ref":"29:2–3; Yochanan 4:5–14","answer":"At the well Yaakov gave, the Shomroni woman asks Yeshua if he is greater than our father Yaakov, and Yeshua says that whoever drinks the water he gives will never thirst.","key":["Yaakov rolled away a stone so that sheep could drink. Yeshua offers water that becomes a spring within.","Both meetings happen at a well, and both change a family line."],"action":"Read Yochanan 4:5–14 beside Bereishit 29:1–10.","detail":"Write down the water you keep going back to that never satisfies. Bring it to יהוה in prayer today."},{"q":"Am I waiting for “all the flocks to gather” before I obey?","ref":"29:7–8","answer":"Yaakov told the shepherds it was still high day and they should water the sheep, but they answered that they could not until all the flocks were gathered.","key":["The shepherds had a rule that kept them sitting at a closed well.","Custom can become an excuse for doing nothing in broad daylight."],"action":"Name one thing you are putting off until “everyone is ready.”","detail":"It may be Shabbat at home, a conversation or a step of obedience. Write down the first move you can make alone, and make it this week."},{"q":"Who will I serve today without being asked?","ref":"29:10","answer":"Yaakov watered Lavan’s flock before anyone asked him and before any wages were mentioned.","key":["Service that waits for a contract is not yet service.","Yaakov gave first, and later he was paid in deceit. He still gave."],"action":"Serve one person today before they ask.","detail":"Choose someone in your home or neighbourhood. Meet one practical need without announcing it."}],"closing":"Others waited for the crowd. Yaakov moved the stone.","actionOfDay":"Before the end of today, identify one task everyone has been leaving for someone else, at home, at work or in your congregation, and finish it yourself without mentioning it."},"af":{"title":"Die Klip op die Put","blessing":"Boker Tov! Mag vandag se Aliyah ons wegbeweeg van wag op ander na doen wat voor ons lê.","hook":"Die herders het gesê die klip kan nie verskuif word voordat al die kuddes bymekaar is nie; Yaakov het Rachel gesien en dit weggerol.","summary":"Yaakov kom in die land van die mense van die ooste en vind ’n put in die veld, met kuddes wat daar lê en ’n groot klip oor die opening. Die herders van Charan sê vir hom hulle ken Lavan, dat dit goed gaan met hom en dat sy dogter Rachel met die skape aankom; hulle sê hulle kan die kuddes nie water gee voordat almal bymekaar is en die klip weggerol is nie. Toe Yaakov vir Rachel sien, rol hy die klip van die put af, gee water vir Lavan se kudde, soen Rachel en huil, en vertel haar dat hy Rivkah se seun is. Lavan hardloop hom tegemoet, neem hom huis toe en noem hom sy been en sy vlees, en ná ’n maand vra hy wat sy loon moet wees; Lavan het twee dogters, Leah die oudste, wie se oë swak was, en Rachel, wat mooi was.","waSummary":"By ’n put in Charan rol Yaakov die klip weg, gee water vir Lavan se kudde en ontmoet Rachel, en Lavan neem hom in sy huis op.","questions":[{"q":"Wat het Yaakov gedoen toe hy Rachel sien?","ref":"29:9–11","answer":"Hy het nader gegaan, die klip van die opening van die put afgerol, Lavan se kudde water gegee, Rachel gesoen en hardop gehuil.","key":["Yaakov se eerste daad in Charan was diens, nie praatjies nie.","Die man wat met ’n klip onder sy kop van die huis weg is, lig nou ’n klip van ’n put af."],"action":"Doen vandag een taak waarvoor ander wag dat iemand anders dit moet doen.","detail":"Soek die “klip op die put” by die huis, by die werk of in jou gemeente, die werk wat almal sien en niemand begin nie. Begin dit."},{"q":"Wat het verander toe Lavan oor loon gevra het?","ref":"29:14–15","answer":"Lavan het Yaakov sy been en sy vlees genoem, en ná ’n maand het hy gevra wat sy loon moet wees.","key":["Die verwelkoming van ’n familielid het die voorwaardes van ’n werkgewer geword.","Lavan se vraag bepaal die toon vir die volgende twintig jaar."],"action":"Let op waar ’n verhouding stilletjies ’n transaksie geword het.","detail":"Dink aan een persoon met wie jy hoofsaaklik omgaan in terme van wat hy jou gee of kos. Doen hierdie week een ding vir hom wat niks terugvra nie."},{"q":"Hoe antwoord Yeshua die vraag wie groter as Yaakov is?","ref":"29:2–3; Yochanan 4:5–14","answer":"By die put wat Yaakov gegee het, vra die Shomroni-vrou vir Yeshua of hy groter is as ons vader Yaakov, en Yeshua sê dat wie drink van die water wat hy gee, nooit weer dors sal kry nie.","key":["Yaakov het ’n klip weggerol sodat skape kon drink. Yeshua bied water aan wat binne-in ’n fontein word.","Albei ontmoetings gebeur by ’n put, en albei verander ’n familielyn."],"action":"Lees Yochanan 4:5–14 saam met Bereishit 29:1–10.","detail":"Skryf die water neer waarna jy telkens teruggaan wat nooit versadig nie. Bring dit vandag in gebed na יהוה."},{"q":"Wag ek dat “al die kuddes bymekaarkom” voordat ek gehoorsaam?","ref":"29:7–8","answer":"Yaakov het vir die herders gesê dit is nog helder oordag en hulle moet die skape water gee, maar hulle het geantwoord dat hulle nie kan voordat al die kuddes bymekaar is nie.","key":["Die herders het ’n reël gehad wat hulle by ’n toe put laat sit het.","Gebruik kan ’n verskoning word om in helder daglig niks te doen nie."],"action":"Noem een ding wat jy uitstel totdat “almal gereed is.”","detail":"Dit kan Shabbat by die huis wees, ’n gesprek of ’n tree van gehoorsaamheid. Skryf die eerste stap neer wat jy alleen kan doen, en doen dit hierdie week."},{"q":"Wie gaan ek vandag dien sonder dat ek gevra word?","ref":"29:10","answer":"Yaakov het Lavan se kudde water gegee voordat iemand hom gevra het en voordat daar enige sprake van loon was.","key":["Diens wat vir ’n kontrak wag, is nog nie diens nie.","Yaakov het eerste gegee, en later is hy met bedrog betaal. Hy het steeds gegee."],"action":"Dien vandag een persoon voordat hy vra.","detail":"Kies iemand in jou huis of buurt. Voorsien in een praktiese behoefte sonder om dit aan te kondig."}],"closing":"Ander het vir die skare gewag. Yaakov het die klip geskuif.","actionOfDay":"Identifiseer voor die einde van vandag een taak wat almal vir iemand anders los, by die huis, by die werk of in jou gemeente, en voltooi dit self sonder om dit te noem."}},{"date":"2026-11-17","parashah":"Vayetze","year":"5787","aliyah":3,"ref":"Bereishit 29:18–30:13","en":{"title":"This Time I Will Praise","blessing":"Boker Tov! May today’s Aliyah turn our longing into praise of יהוה.","hook":"Leah named her first sons after her longing for her husband’s love; the fourth she named after praise of יהוה.","summary":"Yaakov serves Lavan seven years for Rachel, and they seem to him a few days because he loves her. On the wedding night Lavan gives him Leah instead, and when Yaakov protests, Lavan says it is not done in their place to give the younger before the firstborn; Yaakov serves another seven years for Rachel. יהוה sees that Leah is unloved and opens her womb, and she bears Reuven, Shimon, Levi and Yehudah, while Rachel is barren. Rachel envies her sister and gives Yaakov her maid Bilhah, who bears Dan and Naftali; Leah then gives her maid Zilpah, who bears Gad and Asher.","waSummary":"Lavan gives Leah to Yaakov in place of Rachel, and as the two sisters compete, יהוה sees the unloved Leah and opens her womb.","questions":[{"q":"How was Yaakov deceived?","ref":"29:21–26","answer":"Lavan made a feast, brought Leah to Yaakov in the evening, and when Yaakov found it was Leah in the morning, Lavan said it was not done to give the younger before the firstborn.","key":["The man who once told his father he was Esav the firstborn (27:19) is now told that the firstborn comes first.","Yaakov asks Lavan why he deceived him. The question he once caused, he now has to ask."],"action":"Read Bereishit 27:18–24 and 29:21–26 side by side.","detail":"Write down what the two nights have in common. Ask יהוה to show you any deceit of yours that has come back to you."},{"q":"What do Leah’s names for her sons reveal?","ref":"29:31–35","answer":"With Reuven, Shimon and Levi, Leah spoke of יהוה seeing her affliction and of her hope that her husband would love her and be joined to her; with Yehudah she said that this time she would praise יהוה.","key":["Three times she hoped a son would win her husband’s heart.","The fourth time she stopped measuring her life by Yaakov and turned to יהוה. From that son the sceptre will come (49:10)."],"action":"Name the person whose approval you are still trying to win.","detail":"Write it down honestly. Then write one sentence of praise to יהוה that does not depend on that person at all."},{"q":"How does the Haftarah remember these years?","ref":"29:18, 30; Hoshea 12:13","answer":"Hoshea says that Yaakov fled to the field of Aram, and Yisra’el served for a wife, and for a wife he kept sheep.","key":["The prophet sums up fourteen years in one line: he served.","Yisra’el’s story is told through a man who worked long years for what he loved."],"action":"Read Hoshea 12:13–14 beside Bereishit 29:18–30.","detail":"Note the two kinds of keeping in Hoshea: Yaakov kept sheep, and by a prophet Yisra’el was kept. Write down how יהוה has kept you."},{"q":"Am I wrestling with someone close to me for what only Elohim can give?","ref":"30:1–2, 8","answer":"Rachel envied her sister and demanded children from Yaakov, and Yaakov answered in anger that he was not in the place of Elohim; at Naftali’s birth she said she had wrestled with her sister and prevailed.","key":["Rachel fought her sister for what only Elohim could give.","Yaakov’s answer is hard but true: no person can stand in the place of Elohim."],"action":"Stop one competition today.","detail":"Name a sibling, colleague or friend you are measuring yourself against. Pray for their blessing by name today."},{"q":"Will I praise יהוה before my situation changes?","ref":"29:35","answer":"Leah said that this time she would praise יהוה, and named her son Yehudah, even though nothing in the text says her husband’s heart had changed.","key":["Praise did not wait for Yaakov to love her.","Leah’s circumstances stayed the same; her focus changed."],"action":"Write down five things you can praise יהוה for today.","detail":"Choose them from the situation that hurts most. Read the list aloud before you sleep."}],"closing":"Longing names a child after a husband. Praise names him Yehudah.","actionOfDay":"Before you sleep tonight, write down the situation where you most want someone’s love or approval, and under it write five specific reasons to praise יהוה in that same situation. Read them aloud."},"af":{"title":"Hierdie Keer Sal Ek Loof","blessing":"Boker Tov! Mag vandag se Aliyah ons verlange in lof aan יהוה verander.","hook":"Leah het haar eerste seuns vernoem na haar verlange na haar man se liefde; die vierde het sy vernoem na lof aan יהוה.","summary":"Yaakov dien Lavan sewe jaar vir Rachel, en dit is vir hom soos ’n paar dae omdat hy haar liefhet. Op die troufees gee Lavan vir hom Leah in haar plek, en wanneer Yaakov protesteer, sê Lavan dat dit nie by hulle gedoen word om die jongste voor die eersgeborene weg te gee nie; Yaakov dien nog sewe jaar vir Rachel. יהוה sien dat Leah nie bemin word nie en open haar baarmoeder, en sy baar Reuven, Shimon, Levi en Yehudah, terwyl Rachel onvrugbaar is. Rachel is jaloers op haar suster en gee vir Yaakov haar slavin Bilhah, wat Dan en Naftali baar; Leah gee dan haar slavin Zilpah, wat Gad en Asher baar.","waSummary":"Lavan gee Leah aan Yaakov in Rachel se plek, en terwyl die twee susters meeding, sien יהוה die onbeminde Leah en open haar baarmoeder.","questions":[{"q":"Hoe is Yaakov bedrieg?","ref":"29:21–26","answer":"Lavan het ’n fees gehou, Leah saans na Yaakov gebring, en toe Yaakov die oggend sien dat dit Leah is, het Lavan gesê dit word nie gedoen om die jongste voor die eersgeborene weg te gee nie.","key":["Die man wat eens vir sy vader gesê het hy is Esav, die eersgeborene (27:19), hoor nou dat die eersgeborene eerste kom.","Yaakov vra vir Lavan waarom hy hom bedrieg het. Die vraag wat hy eens veroorsaak het, moet hy nou self vra."],"action":"Lees Bereishit 27:18–24 en 29:21–26 langs mekaar.","detail":"Skryf neer wat die twee nagte in gemeen het. Vra יהוה om enige bedrog van jou wat na jou teruggekeer het, aan jou te wys."},{"q":"Wat openbaar Leah se name vir haar seuns?","ref":"29:31–35","answer":"By Reuven, Shimon en Levi het Leah gepraat van יהוה wat haar ellende gesien het en van haar hoop dat haar man haar sal liefhê en aan haar verbonde sal wees; by Yehudah het sy gesê dat sy hierdie keer יהוה sal loof.","key":["Drie keer het sy gehoop dat ’n seun haar man se hart sou wen.","Die vierde keer het sy opgehou om haar lewe aan Yaakov te meet en haar na יהוה gedraai. Uit daardie seun sal die septer kom (49:10)."],"action":"Noem die persoon wie se goedkeuring jy nog probeer wen.","detail":"Skryf dit eerlik neer. Skryf dan een sin van lof aan יהוה wat glad nie van daardie persoon afhang nie."},{"q":"Hoe onthou die Haftarah hierdie jare?","ref":"29:18, 30; Hoshea 12:13","answer":"Hoshea sê dat Yaakov na die veld van Aram gevlug het, en Yisra’el het gedien vir ’n vrou, en vir ’n vrou het hy skape opgepas.","key":["Die profeet som veertien jaar in een reël op: hy het gedien.","Yisra’el se verhaal word vertel deur ’n man wat lang jare gewerk het vir wat hy liefgehad het."],"action":"Lees Hoshea 12:13–14 saam met Bereishit 29:18–30.","detail":"Let op die twee soorte oppas in Hoshea: Yaakov het skape opgepas, en deur ’n profeet is Yisra’el opgepas. Skryf neer hoe יהוה jou bewaar het."},{"q":"Worstel ek met iemand naby my oor wat net Elohim kan gee?","ref":"30:1–2, 8","answer":"Rachel was jaloers op haar suster en het kinders van Yaakov geëis, en Yaakov het kwaad geantwoord dat hy nie in die plek van Elohim is nie; by Naftali se geboorte het sy gesê dat sy met haar suster geworstel en oorwin het.","key":["Rachel het met haar suster geveg oor wat net Elohim kon gee.","Yaakov se antwoord is hard maar waar: geen mens kan in die plek van Elohim staan nie."],"action":"Beëindig vandag een kompetisie.","detail":"Noem ’n broer of suster, kollega of vriend met wie jy jouself meet. Bid vandag by die naam vir sy of haar seën."},{"q":"Sal ek יהוה loof voordat my situasie verander?","ref":"29:35","answer":"Leah het gesê dat sy hierdie keer יהוה sal loof, en haar seun Yehudah genoem, al sê niks in die teks dat haar man se hart verander het nie.","key":["Lof het nie gewag totdat Yaakov haar liefhet nie.","Leah se omstandighede het dieselfde gebly; haar fokus het verander."],"action":"Skryf vandag vyf dinge neer waarvoor jy יהוה kan loof.","detail":"Kies hulle uit die situasie wat die seerste maak. Lees die lys hardop voordat jy gaan slaap."}],"closing":"Verlange vernoem ’n kind na ’n man. Lof noem hom Yehudah.","actionOfDay":"Skryf voordat jy vanaand gaan slaap die situasie neer waar jy die meeste iemand se liefde of goedkeuring wil hê, en skryf daaronder vyf spesifieke redes om יהוה in daardie selfde situasie te loof. Lees dit hardop."}},{"date":"2026-11-18","parashah":"Vayetze","year":"5787","aliyah":4,"ref":"Bereishit 30:14–27","en":{"title":"When Elohim Remembered","blessing":"Boker Tov! May today’s Aliyah teach us to receive from Elohim what we cannot bargain for.","hook":"Rachel bargained for the mandrakes, but she conceived only when Elohim remembered her.","summary":"In the days of the wheat harvest Reuven finds mandrakes in the field and brings them to his mother Leah, and Rachel asks for them. Leah answers that Rachel has already taken her husband, and Rachel trades Yaakov’s night for the mandrakes. Elohim listens to Leah, and she bears Yissachar, Zevulun and a daughter, Dinah; then Elohim remembers Rachel, listens to her and opens her womb, and she bears Yosef, saying that Elohim has taken away her reproach. After Yosef’s birth Yaakov asks Lavan to send him away to his own place, and Lavan answers that he has learned by divination that יהוה has blessed him because of Yaakov.","waSummary":"Rachel trades for Reuven’s mandrakes, yet Leah bears more sons, until Elohim remembers Rachel and she bears Yosef.","questions":[{"q":"What happened with Reuven’s mandrakes?","ref":"30:14–17","answer":"Rachel received the mandrakes in exchange for Yaakov’s night, but Elohim listened to Leah, and Leah conceived and bore Yissachar.","key":["The one who bargained got the plant. The one Elohim heard got the son.","The text gives the credit to Elohim, not to the mandrakes."],"action":"Write down one thing you are trusting to “work” for you.","detail":"A method, a contact or a plan. Ask honestly whether you are trusting it in place of asking Elohim."},{"q":"Who opened Rachel’s womb?","ref":"30:22–24","answer":"Elohim remembered Rachel, listened to her and opened her womb, and she bore Yosef and said that Elohim had taken away her reproach.","key":["Three verbs, all with Elohim as subject: remembered, listened, opened.","Rachel once demanded children from Yaakov. Now she names Elohim as the giver."],"action":"Thank Elohim by name for one gift you once tried to force.","detail":"Write a short prayer naming what He gave in His time. Pray it aloud."},{"q":"How does the Haftarah name the source of fruit?","ref":"30:22–24; Hoshea 14:9","answer":"In the Haftarah יהוה tells Efrayim, a son of Yosef, to have nothing more to do with idols, and says that his fruit is found from Him.","key":["Efrayim descends from the son born in today’s Aliyah.","Rachel learned it at Yosef’s birth; Hoshea calls Yosef’s descendants back to it: fruit comes from יהוה."],"action":"Read Hoshea 14:2–10 beside Bereishit 30:22–24.","detail":"Underline every place Hoshea speaks of growth, fruit or blossom. Write down which of them יהוה claims as His own work."},{"q":"Am I using יהוה’s blessing without seeking יהוה?","ref":"30:27","answer":"Lavan said he had learned by divination that יהוה had blessed him because of Yaakov.","key":["Lavan recognised the blessing and kept the divination.","It is possible to want what יהוה gives without wanting יהוה."],"action":"Name one blessing you enjoy but rarely thank יהוה for.","detail":"Your health, work or family. Thank Him for it specifically today, and ask what He wants from you through it."},{"q":"Will I move when the time has come?","ref":"30:25–26","answer":"After Yosef was born, Yaakov asked Lavan to send him away to his own place and his own land, with his wives and children.","key":["יהוה had promised at Beit-El to bring him back. Yaakov now begins to ask for the road home.","Yaakov named the place he belonged: his own place, his own land."],"action":"Take the first step on one thing יהוה has already told you to do.","detail":"Write down the promise or instruction you have been sitting on. Do one concrete thing toward it this week, such as a phone call, an application or a conversation."}],"closing":"Mandrakes change hands. Only Elohim opens the womb.","actionOfDay":"Today, write down one thing you have been trying to secure by your own means, pray over it aloud by handing it to Elohim, and stop one specific action you were taking to force it."},"af":{"title":"Toe Elohim Onthou Het","blessing":"Boker Tov! Mag vandag se Aliyah ons leer om van Elohim te ontvang wat ons nie kan uitding nie.","hook":"Rachel het vir die liefdesappels gekwansel, maar sy het eers swanger geword toe Elohim aan haar gedink het.","summary":"In die dae van die koringoes kry Reuven liefdesappels in die veld en bring dit na sy moeder Leah, en Rachel vra daarvoor. Leah antwoord dat Rachel reeds haar man weggeneem het, en Rachel ruil Yaakov se nag vir die liefdesappels. Elohim luister na Leah, en sy baar Yissachar, Zevulun en ’n dogter, Dinah; daarna dink Elohim aan Rachel, luister na haar en open haar baarmoeder, en sy baar Yosef en sê dat Elohim haar smaad weggeneem het. Ná Yosef se geboorte vra Yaakov vir Lavan om hom na sy eie plek te laat gaan, en Lavan antwoord dat hy deur waarsêery gewaar het dat יהוה hom ter wille van Yaakov geseën het.","waSummary":"Rachel ruil vir Reuven se liefdesappels, maar Leah baar nog seuns, totdat Elohim aan Rachel dink en sy vir Yosef baar.","questions":[{"q":"Wat het met Reuven se liefdesappels gebeur?","ref":"30:14–17","answer":"Rachel het die liefdesappels gekry in ruil vir Yaakov se nag, maar Elohim het na Leah geluister, en Leah het swanger geword en Yissachar gebaar.","key":["Die een wat gekwansel het, het die plant gekry. Die een wat Elohim gehoor het, het die seun gekry.","Die teks gee die eer aan Elohim, nie aan die liefdesappels nie."],"action":"Skryf een ding neer wat jy vertrou om vir jou te “werk.”","detail":"’n Metode, ’n kontak of ’n plan. Vra eerlik of jy dit vertrou in plaas daarvan om vir Elohim te vra."},{"q":"Wie het Rachel se baarmoeder geopen?","ref":"30:22–24","answer":"Elohim het aan Rachel gedink, na haar geluister en haar baarmoeder geopen, en sy het vir Yosef gebaar en gesê dat Elohim haar smaad weggeneem het.","key":["Drie werkwoorde, almal met Elohim as onderwerp: Hy het gedink, geluister, geopen.","Rachel het eens kinders van Yaakov geëis. Nou noem sy Elohim as die Gewer."],"action":"Dank Elohim by die naam vir een gawe wat jy eens probeer afdwing het.","detail":"Skryf ’n kort gebed wat noem wat Hy op Sy tyd gegee het. Bid dit hardop."},{"q":"Hoe noem die Haftarah die bron van vrug?","ref":"30:22–24; Hoshea 14:9","answer":"In die Haftarah sê יהוה vir Efrayim, ’n seun van Yosef, om niks meer met afgode te doen te hê nie, en sê dat sy vrug uit Hom gevind word.","key":["Efrayim kom uit die seun wat in vandag se Aliyah gebore word.","Rachel het dit by Yosef se geboorte geleer; Hoshea roep Yosef se nageslag daarna terug: vrug kom van יהוה."],"action":"Lees Hoshea 14:2–10 saam met Bereishit 30:22–24.","detail":"Onderstreep elke plek waar Hoshea van groei, vrug of bloei praat. Skryf neer watter daarvan יהוה as Sy eie werk opeis."},{"q":"Gebruik ek יהוה se seën sonder om יהוה te soek?","ref":"30:27","answer":"Lavan het gesê dat hy deur waarsêery gewaar het dat יהוה hom ter wille van Yaakov geseën het.","key":["Lavan het die seën herken en die waarsêery behou.","Dit is moontlik om te wil hê wat יהוה gee sonder om יהוה te wil hê."],"action":"Noem een seën wat jy geniet maar selde vir יהוה voor dank.","detail":"Jou gesondheid, werk of gesin. Dank Hom vandag spesifiek daarvoor, en vra wat Hy deur dit van jou wil hê."},{"q":"Sal ek beweeg wanneer die tyd gekom het?","ref":"30:25–26","answer":"Nadat Yosef gebore is, het Yaakov vir Lavan gevra om hom na sy eie plek en sy eie land te laat gaan, met sy vroue en kinders.","key":["יהוה het by Beit-El belowe om hom terug te bring. Yaakov begin nou vra vir die pad huis toe.","Yaakov het die plek genoem waar hy hoort: sy eie plek, sy eie land."],"action":"Neem die eerste tree in een ding wat יהוה jou reeds gesê het om te doen.","detail":"Skryf die belofte of opdrag neer waarop jy sit. Doen hierdie week een konkrete ding daaraan, soos ’n oproep, ’n aansoek of ’n gesprek."}],"closing":"Liefdesappels verwissel van hande. Net Elohim open die baarmoeder.","actionOfDay":"Skryf vandag een ding neer wat jy met jou eie middele probeer verseker, bid hardop daaroor en gee dit aan Elohim oor, en hou op met een spesifieke ding wat jy gedoen het om dit af te dwing."}},{"date":"2026-11-19","parashah":"Vayetze","year":"5787","aliyah":5,"ref":"Bereishit 30:28–31:16","en":{"title":"Ten Times Changed","blessing":"Boker Tov! May today’s Aliyah give us faithfulness under unfair treatment, knowing that Elohim sees.","hook":"Lavan changed Yaakov’s wages ten times, and Elohim did not allow him to do Yaakov harm.","summary":"Lavan asks Yaakov to name his wages, and Yaakov reminds him that his little flock has increased greatly since he came, because יהוה blessed him at Yaakov’s foot. They agree that the speckled, spotted and dark animals will be Yaakov’s, but that same day Lavan removes them and sends them three days’ journey away; Yaakov uses peeled rods at the watering troughs, and he grows exceedingly rich. When Lavan’s sons accuse him and Lavan’s face changes toward him, יהוה tells Yaakov to return to the land of his fathers and promises to be with him. Yaakov calls Rachel and Leah to the field, tells them that their father deceived him and changed his wages ten times, but Elohim took the livestock and gave it to him, and they answer that he should do whatever Elohim has told him.","waSummary":"Lavan keeps changing Yaakov’s wages, but Elohim prospers Yaakov and tells him it is time to return to the land of his fathers.","questions":[{"q":"What did Lavan do with the agreement?","ref":"30:31–36","answer":"Lavan agreed that the speckled, spotted and dark animals would be Yaakov’s wages, and the same day he removed them, gave them to his sons and put three days’ journey between himself and Yaakov.","key":["Lavan agreed to the terms and emptied the agreement before nightfall.","Yaakov had said his righteousness would answer for him. He let the outcome speak."],"action":"Keep one agreement today exactly as you made it.","detail":"Think of a promise, quote or deadline you have given. Honour it in full, even if circumstances have made it less convenient."},{"q":"To whom does Yaakov give the credit for his wealth?","ref":"31:7–12","answer":"Yaakov told his wives that Elohim did not allow Lavan to harm him, that Elohim took their father’s livestock and gave it to him, and that in a dream the messenger of Elohim said He had seen all that Lavan was doing to him.","key":["The rods are in chapter 30. In chapter 31 Yaakov speaks only of Elohim.","Elohim saw every changed wage before Yaakov said a word."],"action":"Write down one gain you have credited to your own cleverness.","detail":"Rewrite it as a sentence of thanks to Elohim, and say it aloud."},{"q":"How does Yeshua describe a true Yisra’eli?","ref":"31:7; Yochanan 1:47","answer":"When Natan’el comes to him, Yeshua says, here is truly a Yisra’eli in whom there is no deceit.","key":["Today’s Aliyah is full of deceit: changed wages and an emptied agreement.","Yeshua’s first praise of a disciple is for the very thing Lavan’s house lacked."],"action":"Read Yochanan 1:43–51 and Bereishit 31:4–9 together.","detail":"Ask יהוה to show you one area where you shade the truth. Write down what honesty would look like there."},{"q":"Do I serve with all my strength when I am treated unfairly?","ref":"31:6–7","answer":"Yaakov said he had served their father with all his strength, while Lavan deceived him and changed his wages ten times.","key":["Lavan’s unfairness did not lower Yaakov’s standard of work.","Yaakov did not repay deceit with laziness. He left the balance to Elohim."],"action":"Do your work today as if Elohim is your employer.","detail":"Choose the task where you feel least appreciated. Do it fully and well, without complaint."},{"q":"Will I do whatever Elohim has said?","ref":"31:13–16","answer":"Rachel and Leah answered Yaakov that whatever Elohim had said to him, he should do.","key":["The El of Beit-El reminded Yaakov of his vow and told him to arise and go.","The sisters who competed for years now speak with one voice: obey Elohim."],"action":"Act today on one instruction from Elohim you have delayed.","detail":"Write it down. Tell one person in your home what you are going to do, and take the first step before tonight."}],"closing":"Lavan changed the wages ten times. Elohim saw it every time.","actionOfDay":"Before tonight, choose the task where you feel most undervalued and complete it fully and honestly, then write one sentence thanking Elohim that He sees what others do not."},"af":{"title":"Tien Keer Verander","blessing":"Boker Tov! Mag vandag se Aliyah ons getrouheid gee onder onregverdige behandeling, in die wete dat Elohim sien.","hook":"Lavan het Yaakov se loon tien keer verander, en Elohim het hom nie toegelaat om Yaakov kwaad te doen nie.","summary":"Lavan vra Yaakov om sy loon te noem, en Yaakov herinner hom dat sy klein kudde baie vermeerder het sedert hy gekom het, omdat יהוה hom op Yaakov se voetspoor geseën het. Hulle kom ooreen dat die gespikkelde, gevlekte en donker diere Yaakov s’n sal wees, maar dieselfde dag haal Lavan hulle uit en stuur hulle drie dagreise ver; Yaakov gebruik afgeskilde latte by die drinkbakke, en hy word baie ryk. Wanneer Lavan se seuns hom beskuldig en Lavan se gesig teenoor hom verander, sê יהוה vir Yaakov om terug te keer na die land van sy vaders en belowe om by hom te wees. Yaakov roep Rachel en Leah na die veld, vertel hulle dat hulle vader hom bedrieg en sy loon tien keer verander het, maar dat Elohim die vee weggeneem en aan hom gegee het, en hulle antwoord dat hy moet doen wat Elohim vir hom gesê het.","waSummary":"Lavan verander telkens Yaakov se loon, maar Elohim laat Yaakov voorspoedig wees en sê vir hom dit is tyd om terug te keer na die land van sy vaders.","questions":[{"q":"Wat het Lavan met die ooreenkoms gedoen?","ref":"30:31–36","answer":"Lavan het ingestem dat die gespikkelde, gevlekte en donker diere Yaakov se loon sal wees, en dieselfde dag het hy hulle uitgehaal, aan sy seuns gegee en drie dagreise tussen homself en Yaakov gesit.","key":["Lavan het tot die voorwaardes ingestem en die ooreenkoms voor sononder leeggemaak.","Yaakov het gesê sy geregtigheid sal vir hom antwoord. Hy het die uitkoms laat praat."],"action":"Hou vandag een ooreenkoms presies soos jy dit gemaak het.","detail":"Dink aan ’n belofte, kwotasie of sperdatum wat jy gegee het. Eer dit ten volle, selfs al het omstandighede dit minder gerieflik gemaak."},{"q":"Aan wie gee Yaakov die eer vir sy rykdom?","ref":"31:7–12","answer":"Yaakov het vir sy vroue gesê dat Elohim Lavan nie toegelaat het om hom kwaad te doen nie, dat Elohim hulle vader se vee weggeneem en aan hom gegee het, en dat die boodskapper van Elohim in ’n droom gesê het dat Hy alles gesien het wat Lavan aan hom doen.","key":["Die latte is in hoofstuk 30. In hoofstuk 31 praat Yaakov net van Elohim.","Elohim het elke veranderde loon gesien voordat Yaakov ’n woord gesê het."],"action":"Skryf een wins neer wat jy aan jou eie slimheid toegeskryf het.","detail":"Herskryf dit as ’n sin van dank aan Elohim, en sê dit hardop."},{"q":"Hoe beskryf Yeshua ’n ware Yisra’eliet?","ref":"31:7; Yochanan 1:47","answer":"Wanneer Natan’el na hom toe kom, sê Yeshua: hier is waarlik ’n Yisra’eliet in wie daar geen bedrog is nie.","key":["Vandag se Aliyah is vol bedrog: veranderde lone en ’n leeggemaakte ooreenkoms.","Yeshua se eerste lof vir ’n dissipel is juis vir wat Lavan se huis kortgekom het."],"action":"Lees Yochanan 1:43–51 en Bereishit 31:4–9 saam.","detail":"Vra יהוה om een terrein aan jou te wys waar jy die waarheid buig. Skryf neer hoe eerlikheid daar sou lyk."},{"q":"Dien ek met al my krag wanneer ek onregverdig behandel word?","ref":"31:6–7","answer":"Yaakov het gesê dat hy hulle vader met al sy krag gedien het, terwyl Lavan hom bedrieg en sy loon tien keer verander het.","key":["Lavan se onregverdigheid het Yaakov se standaard van werk nie verlaag nie.","Yaakov het bedrog nie met luiheid vergeld nie. Hy het die afrekening aan Elohim oorgelaat."],"action":"Doen vandag jou werk asof Elohim jou werkgewer is.","detail":"Kies die taak waar jy die minste waardeer voel. Doen dit volledig en goed, sonder om te kla."},{"q":"Sal ek doen wat Elohim gesê het?","ref":"31:13–16","answer":"Rachel en Leah het vir Yaakov geantwoord dat hy alles moet doen wat Elohim vir hom gesê het.","key":["Die El van Beit-El het Yaakov aan sy gelofte herinner en vir hom gesê om op te staan en te gaan.","Die susters wat jare lank meegeding het, praat nou met een stem: gehoorsaam Elohim."],"action":"Tree vandag op na aanleiding van een opdrag van Elohim wat jy uitgestel het.","detail":"Skryf dit neer. Vertel een persoon in jou huis wat jy gaan doen, en neem die eerste tree voor vanaand."}],"closing":"Lavan het die loon tien keer verander. Elohim het dit elke keer gesien.","actionOfDay":"Kies voor vanaand die taak waar jy die minste waardeer voel en voltooi dit volledig en eerlik, en skryf dan een sin waarin jy Elohim dank dat Hy sien wat ander nie sien nie."}},{"date":"2026-11-20","parashah":"Vayetze","year":"5787","aliyah":6,"ref":"Bereishit 31:17–42","en":{"title":"Neither Good nor Bad","blessing":"Boker Tov! May today’s Aliyah show us that no hand can harm us when Elohim has spoken.","hook":"Lavan pursued Yaakov for seven days, and one word from Elohim in the night held back his hand.","summary":"While Lavan is away shearing his sheep, Yaakov sets his family on camels and leaves for Kna’an without telling him, and Rachel steals her father’s terafim. Lavan pursues for seven days and overtakes him in the hills of Gil’ad, but Elohim comes to Lavan in a dream and warns him not to speak to Yaakov either good or bad. Lavan accuses Yaakov of stealing away and of stealing his gods, and searches every tent, but Rachel hides the terafim in the camel’s saddle and sits on them. Yaakov then answers Lavan with twenty years of faithful service, ewes that never miscarried, losses he bore himself, heat by day and frost by night, and says that if the Elohim of his father had not been with him, Lavan would have sent him away empty.","waSummary":"Yaakov flees from Lavan, Rachel steals the terafim, and when Lavan overtakes them, Elohim warns him in a dream not to harm Yaakov.","questions":[{"q":"What did Elohim tell Lavan?","ref":"31:24, 29","answer":"Elohim came to Lavan in a dream by night and told him to take care not to speak to Yaakov either good or bad.","key":["Lavan admits it himself: it was in the power of his hand to do harm, but the Elohim of Yaakov’s father had spoken.","Seven days of pursuit were undone by one sentence in the night."],"action":"Write down the “Lavan” who seems to hold power over you.","detail":"Under it write Bereishit 31:29. Pray that Elohim will speak where you cannot."},{"q":"What do Rachel’s terafim reveal?","ref":"31:19, 30–35","answer":"Rachel stole her father’s terafim, Lavan called them his gods, and they lay hidden in a camel’s saddle with Rachel sitting on them while Lavan searched.","key":["Lavan’s gods had to be stolen, carried and hidden. They could not even be found by their owner.","Idols had come along into the camp of the man who met Elohim at Beit-El."],"action":"Search your own “tent” for something that does not belong in a home that serves יהוה.","detail":"An object, a habit or a source of security. Remove it before Shabbat."},{"q":"What does the Haftarah say Yisra’el must confess about idols?","ref":"31:30; Hoshea 14:4","answer":"In the Haftarah Yisra’el is told to return and to say that they will no longer call the work of their hands their gods.","key":["Lavan accused Yaakov of stealing his gods. Hoshea teaches Yisra’el to confess that the work of their hands is not their god.","Gods that can be stolen were made by hands. יהוה made the hands."],"action":"Read Hoshea 14:2–4 aloud as a prayer.","detail":"Replace the general words with your own specifics: name what you will no longer call your help."},{"q":"Do I flee in fear instead of trusting Elohim to speak?","ref":"31:20, 31","answer":"Yaakov left without telling Lavan, and when Lavan asked why, Yaakov said he had been afraid that Lavan would take his daughters by force.","key":["יהוה had told Yaakov to return. Fear decided how he left.","Elohim protected him anyway, but the secrecy made Lavan’s accusation possible."],"action":"Have one honest conversation you have been avoiding out of fear.","detail":"Prepare your words in prayer. Speak plainly and leave the outcome to Elohim."},{"q":"Will I be faithful when no one is checking?","ref":"31:38–40","answer":"Yaakov said that for twenty years Lavan’s ewes and goats had not miscarried, he had not eaten Lavan’s rams, he bore the loss of what was torn, and he endured heat by day and frost by night.","key":["Most of that faithfulness happened in the fields, at night, unseen.","Yaakov’s defence was not words but twenty years of work."],"action":"Finish one unseen task today with full care before Shabbat begins.","detail":"Choose something no one will inspect, and do it as if Elohim is watching, because He is."}],"closing":"Lavan had the power of his hand. Elohim had the last word.","actionOfDay":"Before Shabbat begins tonight, go through your home and remove one object, habit or source of security that competes with יהוה, and say aloud that it is no longer your help."},"af":{"title":"Nie Goed of Sleg Nie","blessing":"Boker Tov! Mag vandag se Aliyah ons wys dat geen hand ons kan skade aandoen wanneer Elohim gepraat het nie.","hook":"Lavan het Yaakov sewe dae lank agtervolg, en een woord van Elohim in die nag het sy hand teruggehou.","summary":"Terwyl Lavan weg is om sy skape te skeer, sit Yaakov sy gesin op kamele en vertrek na Kna’an sonder om hom te vertel, en Rachel steel haar vader se terafim. Lavan jaag hom sewe dae lank agterna en haal hom in die berge van Gil’ad in, maar Elohim kom in ’n droom na Lavan en waarsku hom om met Yaakov nie goed of sleg te praat nie. Lavan beskuldig Yaakov dat hy weggesluip en sy gode gesteel het, en deursoek elke tent, maar Rachel steek die terafim in die kameel se saal weg en sit daarop. Yaakov antwoord Lavan dan met twintig jaar se getroue diens, ooie wat nooit gemis het nie, verliese wat hy self gedra het, hitte bedags en ryp snags, en sê dat as die Elohim van sy vader nie by hom was nie, Lavan hom met leë hande sou weggestuur het.","waSummary":"Yaakov vlug van Lavan af, Rachel steel die terafim, en wanneer Lavan hulle inhaal, waarsku Elohim hom in ’n droom om Yaakov nie kwaad te doen nie.","questions":[{"q":"Wat het Elohim vir Lavan gesê?","ref":"31:24, 29","answer":"Elohim het in ’n droom in die nag na Lavan gekom en vir hom gesê om op te pas dat hy met Yaakov nie goed of sleg praat nie.","key":["Lavan erken dit self: dit was in die mag van sy hand om skade te doen, maar die Elohim van Yaakov se vader het gepraat.","Sewe dae van agtervolging is deur een sin in die nag ongedaan gemaak."],"action":"Skryf die “Lavan” neer wat skynbaar mag oor jou het.","detail":"Skryf Bereishit 31:29 daaronder. Bid dat Elohim sal praat waar jy nie kan nie."},{"q":"Wat openbaar Rachel se terafim?","ref":"31:19, 30–35","answer":"Rachel het haar vader se terafim gesteel, Lavan het dit sy gode genoem, en dit het weggesteek gelê in ’n kameel se saal met Rachel wat daarop sit terwyl Lavan soek.","key":["Lavan se gode moes gesteel, gedra en weggesteek word. Selfs hulle eienaar kon hulle nie vind nie.","Afgode het saamgekom in die kamp van die man wat Elohim by Beit-El ontmoet het."],"action":"Deursoek jou eie “tent” vir iets wat nie hoort in ’n huis wat יהוה dien nie.","detail":"’n Voorwerp, ’n gewoonte of ’n bron van sekuriteit. Verwyder dit voor Shabbat."},{"q":"Wat sê die Haftarah moet Yisra’el oor afgode bely?","ref":"31:30; Hoshea 14:4","answer":"In die Haftarah word vir Yisra’el gesê om terug te keer en te sê dat hulle die werk van hulle hande nie meer hulle gode sal noem nie.","key":["Lavan het Yaakov daarvan beskuldig dat hy sy gode gesteel het. Hoshea leer Yisra’el om te bely dat die werk van hulle hande nie hulle god is nie.","Gode wat gesteel kan word, is deur hande gemaak. יהוה het die hande gemaak."],"action":"Lees Hoshea 14:2–4 hardop as ’n gebed.","detail":"Vervang die algemene woorde met jou eie besonderhede: noem wat jy nie meer jou hulp sal noem nie."},{"q":"Vlug ek uit vrees in plaas daarvan om Elohim te vertrou om te praat?","ref":"31:20, 31","answer":"Yaakov het vertrek sonder om Lavan te vertel, en toe Lavan vra waarom, het Yaakov gesê hy was bang dat Lavan sy dogters met geweld sou wegneem.","key":["יהוה het vir Yaakov gesê om terug te keer. Vrees het bepaal hoe hy vertrek het.","Elohim het hom tog beskerm, maar die geheimhouding het Lavan se beskuldiging moontlik gemaak."],"action":"Voer een eerlike gesprek wat jy uit vrees vermy het.","detail":"Berei jou woorde in gebed voor. Praat reguit en laat die uitkoms aan Elohim oor."},{"q":"Sal ek getrou wees wanneer niemand kyk nie?","ref":"31:38–40","answer":"Yaakov het gesê dat Lavan se ooie en bokke twintig jaar lank nie gemis het nie, dat hy nie Lavan se ramme geëet het nie, dat hy die verlies van wat verskeur is self gedra het, en dat hy hitte bedags en ryp snags verduur het.","key":["Die meeste van daardie getrouheid het in die veld gebeur, in die nag, ongesien.","Yaakov se verweer was nie woorde nie, maar twintig jaar se werk."],"action":"Voltooi vandag een ongesiene taak met volle sorg voordat Shabbat begin.","detail":"Kies iets wat niemand gaan nagaan nie, en doen dit asof Elohim kyk, want Hy kyk."}],"closing":"Lavan het die mag van sy hand gehad. Elohim het die laaste woord gehad.","actionOfDay":"Gaan voordat Shabbat vanaand begin deur jou huis en verwyder een voorwerp, gewoonte of bron van sekuriteit wat met יהוה meeding, en sê hardop dat dit nie meer jou hulp is nie."}},{"date":"2026-11-21","parashah":"Vayetze","year":"5787","aliyah":7,"ref":"Bereishit 31:43–32:3","en":{"title":"The Camp of Elohim","blessing":"Boker Tov and Shabbat Shalom! May today’s Aliyah show us that the camp of Elohim surrounds those who walk in His promise.","hook":"Yaakov left the land with messengers of Elohim at Beit-El, and he returns to be met by them at Machanayim.","summary":"Lavan claims that the daughters, the children and the flocks are all his, but proposes a covenant as a witness between them. Yaakov sets up a stone as a pillar, his relatives gather stones into a heap, and they eat there; Lavan calls it Yegar-Sahaduta and Yaakov calls it Gal’ed, and it is also called Mitzpah, because Lavan says that יהוה must watch between them when they are apart. They agree that neither will pass the heap to harm the other, Yaakov swears by the Fear of his father Yitzchak, offers a sacrifice on the mountain and calls his relatives to eat bread. In the morning Lavan kisses his grandchildren and daughters, blesses them and returns home; Yaakov goes on his way, messengers of Elohim meet him, and he names the place Machanayim, saying this is the camp of Elohim.","waSummary":"Yaakov and Lavan make a covenant at Gal’ed and part in peace, and as Yaakov goes on, messengers of Elohim meet him at Machanayim.","questions":[{"q":"What did Yaakov and Lavan set up between them?","ref":"31:44–52","answer":"They set up a stone pillar and a heap of stones as a witness, and agreed that neither would pass beyond it to harm the other.","key":["Lavan gave the heap an Aramaic name and Yaakov a Hebrew one. Same stones, two languages, one boundary.","Twenty years ended not with revenge but with a witness."],"action":"Set one clear boundary today where there has been ongoing harm.","detail":"Name the relationship. Decide in prayer what you will no longer allow, and state it calmly and plainly."},{"q":"What does Mitzpah really express?","ref":"31:49–50","answer":"Lavan said יהוה must watch between him and Yaakov when they are hidden from each other, and that Elohim is witness if Yaakov mistreats his daughters.","key":["Mitzpah is not a sentimental farewell. It is the language of a man who no longer trusts, handing the matter over to Elohim.","Where people cannot see, Elohim still watches."],"action":"Hand over to Elohim one situation you cannot watch.","detail":"A child far away, a business partner or a family dispute. Pray Bereishit 31:49 over it by name, and stop trying to control it."},{"q":"How does the Haftarah describe the way יהוה kept Yisra’el?","ref":"31:38–41; Hoshea 12:13–14","answer":"Hoshea says Yisra’el served for a wife and kept sheep, and that by a prophet יהוה brought Yisra’el up from Egypt and by a prophet he was kept.","key":["Yaakov kept Lavan’s flocks for twenty years. יהוה kept Yaakov through every one of them.","The Shepherd who watched the shepherd later led the whole nation out."],"action":"Read Hoshea 12:13–14 and Bereishit 28:15 together.","detail":"Write down three ways יהוה kept His promise to keep you this past year."},{"q":"Can I eat bread with the people who wronged me?","ref":"31:54–32:1","answer":"Yaakov offered a sacrifice on the mountain and called his relatives to eat bread, and in the morning Lavan kissed his children and blessed them before he went home.","key":["The covenant was sealed at a table, not on a battlefield.","Yaakov did not pretend the wrong never happened. He named it, set a boundary and then shared bread."],"action":"Bless one person this Shabbat who has hurt you in the past.","detail":"Pray for them by name at your Shabbat table, or send them one honest word of blessing."},{"q":"Will I recognise the camp of Elohim around me this Shabbat?","ref":"32:2–3","answer":"As Yaakov went on his way, messengers of Elohim met him, and when he saw them he said this is the camp of Elohim and named the place Machanayim.","key":["At Beit-El he did not know; at Machanayim he saw and named it immediately.","יהוה kept the promise of Beit-El on the road home."],"action":"Name the evidence of Elohim’s camp around you this week.","detail":"At your Shabbat table, let each person name one place they saw יהוה’s protection or provision this week."}],"closing":"At Beit-El he did not know. At Machanayim he saw it and named it.","actionOfDay":"At your Shabbat table today, read Bereishit 28:15 and 32:2–3 aloud, and let each person name one specific place where they saw יהוה keep them this week.","deeper":"The Haftarah, Hoshea 12:13–14:10, opens with this Parashah in one line: Yaakov fled to the field of Aram, Yisra’el served for a wife and kept sheep, and by a prophet יהוה brought Yisra’el out of Egypt and kept him (Hoshea 12:13–14). It then calls Efrayim to return, to bring words instead of idols and to confess that Ashur will not save and the work of their hands is not their elohim (14:2–4), and ends with יהוה saying that Efrayim’s fruit is found from Him (14:9), the same lesson Rachel learned when Elohim opened her womb and she bore Yosef (Bereishit 30:22–24). In Yochanan 1:43–51 Yeshua calls Natan’el a Yisra’eli in whom there is no deceit, and promises that he will see heaven opened and the messengers of Elohim going up and coming down on the Son of Adam, taking the ladder of Beit-El (Bereishit 28:12) and placing himself at its foot. The Parashah begins and ends with messengers of Elohim, and the Brit Chadashah shows who stands where the ladder stood."},"af":{"title":"Die Kamp van Elohim","blessing":"Boker Tov en Shabbat Shalom! Mag vandag se Aliyah ons wys dat die kamp van Elohim dié omring wat in Sy belofte wandel.","hook":"Yaakov het die land verlaat met boodskappers van Elohim by Beit-El, en hy keer terug om deur hulle by Machanayim ontmoet te word.","summary":"Lavan beweer dat die dogters, die kinders en die kuddes almal syne is, maar stel ’n verbond voor as getuie tussen hulle. Yaakov rig ’n klip as gedenksteen op, sy familie maak ’n hoop klippe bymekaar, en hulle eet daar; Lavan noem dit Yegar-Sahaduta en Yaakov noem dit Gal’ed, en dit word ook Mitzpah genoem, omdat Lavan sê dat יהוה tussen hulle moet wag hou wanneer hulle van mekaar af is. Hulle kom ooreen dat nie een die hoop sal oorsteek om die ander kwaad te doen nie, Yaakov sweer by die Vrees van sy vader Yitzchak, bring ’n offer op die berg en nooi sy familie om brood te eet. Die oggend soen Lavan sy kleinkinders en dogters, seën hulle en gaan huis toe; Yaakov gaan verder op sy pad, boodskappers van Elohim ontmoet hom, en hy noem die plek Machanayim en sê dat dit die kamp van Elohim is.","waSummary":"Yaakov en Lavan sluit ’n verbond by Gal’ed en skei in vrede, en terwyl Yaakov verder gaan, ontmoet boodskappers van Elohim hom by Machanayim.","questions":[{"q":"Wat het Yaakov en Lavan tussen hulle opgerig?","ref":"31:44–52","answer":"Hulle het ’n klippilaar en ’n hoop klippe as getuie opgerig, en ooreengekom dat nie een verby dit sal gaan om die ander kwaad te doen nie.","key":["Lavan het die hoop ’n Aramese naam gegee en Yaakov ’n Hebreeuse naam. Dieselfde klippe, twee tale, een grens.","Twintig jaar het nie met wraak geëindig nie, maar met ’n getuie."],"action":"Stel vandag een duidelike grens waar daar voortdurende skade was.","detail":"Noem die verhouding. Besluit in gebed wat jy nie meer gaan toelaat nie, en sê dit kalm en duidelik."},{"q":"Wat druk Mitzpah eintlik uit?","ref":"31:49–50","answer":"Lavan het gesê dat יהוה tussen hom en Yaakov moet wag hou wanneer hulle vir mekaar verborge is, en dat Elohim getuie is as Yaakov sy dogters sleg behandel.","key":["Mitzpah is nie ’n sentimentele afskeid nie. Dit is ’n man wat nie meer vertrou nie en die saak aan Elohim oorgee.","Waar mense nie kan sien nie, hou Elohim steeds wag."],"action":"Gee een situasie wat jy nie kan dophou nie, aan Elohim oor.","detail":"’n Kind ver weg, ’n sakevennoot of ’n familietwis. Bid Bereishit 31:49 by die naam daaroor, en hou op om dit te probeer beheer."},{"q":"Hoe beskryf die Haftarah die manier waarop יהוה Yisra’el bewaar het?","ref":"31:38–41; Hoshea 12:13–14","answer":"Hoshea sê dat Yisra’el gedien het vir ’n vrou en skape opgepas het, en dat יהוה Yisra’el deur ’n profeet uit Egipte laat optrek het en dat hy deur ’n profeet bewaar is.","key":["Yaakov het twintig jaar lank Lavan se kuddes opgepas. יהוה het Yaakov deur elkeen van daardie jare bewaar.","Die Herder wat oor die herder gewaak het, het later die hele volk uitgelei."],"action":"Lees Hoshea 12:13–14 en Bereishit 28:15 saam.","detail":"Skryf drie maniere neer waarop יהוה die afgelope jaar Sy belofte gehou het om jou te bewaar."},{"q":"Kan ek brood eet saam met die mense wat my verontreg het?","ref":"31:54–32:1","answer":"Yaakov het ’n offer op die berg gebring en sy familie geroep om brood te eet, en die oggend het Lavan sy kinders gesoen en geseën voordat hy huis toe is.","key":["Die verbond is by ’n tafel beseël, nie op ’n slagveld nie.","Yaakov het nie voorgegee dat die onreg nooit gebeur het nie. Hy het dit benoem, ’n grens gestel en toe brood gedeel."],"action":"Seën hierdie Shabbat een persoon wat jou in die verlede seergemaak het.","detail":"Bid by die naam vir hom of haar by jou Shabbat-tafel, of stuur een eerlike woord van seën."},{"q":"Sal ek hierdie Shabbat die kamp van Elohim rondom my herken?","ref":"32:2–3","answer":"Terwyl Yaakov op pad was, het boodskappers van Elohim hom ontmoet, en toe hy hulle sien, het hy gesê dat dit die kamp van Elohim is en die plek Machanayim genoem.","key":["By Beit-El het hy nie geweet nie; by Machanayim het hy dadelik gesien en dit benoem.","יהוה het die belofte van Beit-El op die pad huis toe gehou."],"action":"Noem die bewyse van Elohim se kamp rondom jou hierdie week.","detail":"Laat elke persoon by jou Shabbat-tafel een plek noem waar hulle hierdie week יהוה se beskerming of voorsiening gesien het."}],"closing":"By Beit-El het hy nie geweet nie. By Machanayim het hy gesien en dit benoem.","actionOfDay":"Lees vandag by jou Shabbat-tafel Bereishit 28:15 en 32:2–3 hardop, en laat elke persoon een spesifieke plek noem waar hulle hierdie week gesien het dat יהוה hulle bewaar het.","deeper":"Die Haftarah, Hoshea 12:13–14:10, open met hierdie Parashah in een reël: Yaakov het na die veld van Aram gevlug, Yisra’el het gedien vir ’n vrou en skape opgepas, en deur ’n profeet het יהוה Yisra’el uit Egipte gebring en hom bewaar (Hoshea 12:13–14). Daarna roep dit Efrayim om terug te keer, om woorde te bring in plaas van afgode en te bely dat Ashur nie sal red nie en dat die werk van hulle hande nie hulle elohim is nie (14:2–4), en dit eindig met יהוה wat sê dat Efrayim se vrug uit Hom gevind word (14:9), dieselfde les wat Rachel geleer het toe Elohim haar baarmoeder geopen het en sy Yosef gebaar het (Bereishit 30:22–24). In Yochanan 1:43–51 noem Yeshua vir Natan’el ’n Yisra’eliet in wie daar geen bedrog is nie, en belowe dat hy die hemel oop sal sien en die boodskappers van Elohim wat op die Seun van Adam opklim en afkom; hy neem die leer van Beit-El (Bereishit 28:12) en plaas homself aan die voet daarvan. Die Parashah begin en eindig met boodskappers van Elohim, en die Brit Chadashah wys wie staan waar die leer gestaan het."}}];

